WITH payload AS (SELECT $archive_payload$[{"id":"5ced4c2f-734b-5bab-898c-7ec85c6d54da","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أرض زراعية على دفعات -اإلتفاق على الغاء عقد املبايعة وإعادة ثمن األرض -قيام املدعى عليه بسداد جزء من املبلغ -املطالبة بسداد باقي املبلغ -إقرار املدعى عليه بإلغاء املبايعة شفهيا -القضاء بالشاهد واليمن -إلزام املدعى عليه بدفع املبلغ املدعى به أصالة .","document_number":"34172977","case_number":"32142390","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/28","year":"1434","subject":"عقار -شراء أرض زراعية على دفعات -اإلتفاق على الغاء عقد املبايعة وإعادة ثمن األرض -قيام املدعى عليه بسداد جزء من املبلغ -املطالبة بسداد باقي املبلغ -إقرار املدعى عليه بإلغاء املبايعة شفهيا -القضاء بالشاهد واليمن -إلزام املدعى عليه بدفع املبلغ املدعى به أصالة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34172977 :‬تاريخه ‪1434/3/28 :‬هـ‬\n                  ‫رقم الدعوى ‪32142390 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34277832:‬تاريخه‪1434/07/24:‬هـ‬\n\n\n‫عقــار‪ -‬شــراء أرض زراعيــة علــى دفعــات‪ -‬اإلتفــاق علــى الغــاء عقــد‬\n‫املبايعــة وإعــادة ثمــن األرض‪ -‬قيــام املدعــى عليــه بســداد جــزء مــن‬\n‫املبلــغ‪ -‬املطالبــة بســداد باقــي املبلــغ‪ -‬إقــرار املدعــى عليــه بإلغــاء املبايعة‬\n‫شــفهيا‪ -‬القضــاء بالشــاهد واليمــن‪ -‬إلــزام املدعــى عليــه بدفــع املبلــغ‬\n                                                              ‫املدعــى بــه أصالــة ‪.‬‬\n\n\n\n‫‪ -1‬مــا قــرره أكثــر أهــل العلــم مــن ثبــوت املــال ملدعيــه بشــاهد وميــن‬\n‫وهــو رأي اخللفــاء الراشــدين األربعــة والفقهــاء الســبعة واحلنابلــة‬\n                                    ‫ومالــك والشــافعي املغنــي ‪. 130/14‬‬\n‫‪ -2‬ملــا رواه ســهيل عــن أبيــه عــن أبــي هريــرة رضــي اهلل عنــه قــال قضــى‬\n‫رســول اهلل صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد الواحــد‪ .‬رواه‬\n                                            ‫ســعيد بــن منصــور يف ســننه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى وكالــة بــأن موكلــه اتفــق مــع املدعــى عليــه علــى شــراء‬\n‫أرض زراعيــة (ذكــر وصفهــا) مببلــغ ذكــر قــدره ســلم موكلــه اجلــزء‬\n‫األكبــر مــن املبلــغ علــى دفعــات‪ -‬ثــم اتفقــا علــى إلغــاء املبايعــة وإعــادة‬\n‫املبلــغ املســمى‪ -‬بنــاء عليــه ســدد املدعــى عليــه جــزء ًا مــن املبلــغ وتقبــى يف‬\n\n                                                                                           ‫‪460‬‬\n\f      ‫ذمتــه جــزء ًا آخــر (ذكــر مقــداره) طلــب املدعــي وكالــه إلــزام املدعــى‬\n      ‫عليــه بــأن يدفــع ملوكلــه املبلــغ املتبقــي‪ -‬أقــر املدعــى عليــه بالبيــع‬\n      ‫وأنكــر مقــدار املبلــغ املســتلم وانكــر الغــاء املبايعــة شــفهياً‪ -‬احضــر‬\n      ‫املدعــى شــاهدين ورصــدت شــهادتهما‪ -‬جــرى تعديــل الشــاهد األول ألن‬\n      ‫شــهادته موصلــه‪ -‬حلــف املدعــي أصالــة اليمــن تكملــه لبينتــه‪ -‬كمــا‬\n      ‫أبــرز املدعــي خمــس ورقــات رصــد مضمونهــا‪ -‬كمــا رصــد مضمــون‬\n      ‫جــواب مؤسســة النقــد‪ -‬لقضــاء النبــي صلــى اهلل عليــه وســلم بالشــاهد‬\n      ‫مــع اليمــن وهــو قــول أكثــر الفقهــاء لــذا صــدر احلكــم علــى املدعــى‬\n      ‫عليــه بــأن يدفــع للمدعــى أصالــة املبلــغ املدعــى بــه‪ -‬لــم يقنــع املدعــى‬\n                    ‫عليــه باحلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫العامــة‬\n          ‫ّ‬    ‫احلمــد هلل وحــده وبعــد ‪ ،‬فلــدي أنــا ‪...‬القاضــي يف احملكمــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫العامــة مبحافظــة القطيــف برقــم ‪32142390‬‬       ‫َ‬    ‫رئيــس احملكمــة‬\n      ‫وتاريــخ ‪1432/4/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32447278‬وتاريــخ‬\n      ‫‪1432/4/25‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1432/12/20‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة صباح ـ ًا وفيهــا حضــر ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬بصفتــه الوكيــل الشــرعي‬\n      ‫عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بالدمــام برقــم ‪ 52171‬يف‬\n      ‫‪1431/11/2‬ه ـ وادعــى علــى احلاضــر معــه ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫ا يف دعــواه ‪ :‬لقــد اتفــق موكلــي مــع املدعــى‬\n                                                      ‫الســجل املدنــي رقــم ‪...‬قائـ ً‬\n\n‫‪461‬‬\n\f‫عليــه هــذا احلاضــر بــأن يشــتري منــه األرض الزراعيــة املســماة ‪ ...‬الواقعــة‬\n‫بســيحة اجلريعــة التابعــة لســيهات مببلــغ قــدره مائتــا ألــف ريــال وكان‬\n‫ذلــك بتاريــخ ‪1428/8/3‬ه ـ وقــد ســلم موكلــي للمدعــى عليــه مبلغ ـ ًا‬\n‫قــدره مائــة وخمســة وثمانــون ألــف ريــال علــى دفعــات ثــم إنــه يف شــهر‬\n‫رمضــان لعــام ‪1431‬ه ـ اتفــق موكلــي مــع املدعــى عليــه علــى إلغــاء‬\n‫املبايعــة وإعــادة املائــة وخمســة وثمانــن ألــف ريــال ملوكلــي وبنــاء ً علــى‬\n‫ذلــك ســدد املدعــى عليــه ملوكلــي اثنــن وخمســن ألــف ريــال وتبقــى‬\n‫يف ذمتــه مائــة وثالثــة وثالثــن ألــف ريــال لــم يســددها ملوكلــي حتــى‬\n‫اآلن لــذا أطلــب إلــزام املدعــى عليــه بــأن يدفــع ملوكلــي مبلغ ـ ًا قــدره‬\n‫مائــة وثالثــة وثالثــون ألــف ريــال هــذه دعــواي ‪ ،‬وباســتجواب املدعــى‬\n‫عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه مــن أننــي‬\n‫بعــت علــى موكلــه األرض الزراعيــة املوصوفــة يف الدعــوى مببلــغ مائتــي‬\n‫ألــف ريــال فهــذا صحيــح وأمــا مــا ذكــره مــن أن موكلــه ســلم لــي مائــة‬\n‫وخمســة وثمانــن ألــف مــن القيمــة أو أننــا اتفقنــا علــى إلغــاء املبايعــة‬\n‫فهــذا كلــه غيــر صحيــح هــذا مــا أجــاب بــه ‪ ،‬وبطلــب البينــة مــن املدعــي‬\n‫وكالــة علــى مــا ذكــره مــن إلغــاء املبايعــة املذكــورة قــال ‪ :‬نعــم لــدي‬\n‫البينــة وســوف أحضرهــا يف اجللســة القادمــة ‪ ،‬ثــم إنــه يف جلســة أخــرى‬\n‫حضــر املدعــي أصالــة ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪...‬وحضــر حلضــوره املدعــى عليــه ‪ ،...‬وبســؤال املدعــي عمــا وعــد بــه‬\n‫وكيلــه مــن بينــة أحضــر للشــهادة وأدائهــا ‪...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه شــهد بقولــه ‪ :‬أشــهد بــاهلل‬\n‫العظيــم بأنــه قبــل أربــع أو خمــس ســنوات تقريبـ ًا اشــترى املدعــي ‪...‬هــذا‬\n‫احلاضــر مــن املدعــى عليــه ‪...‬هــذا احلاضــر معنــا أرض زراعيــة تقــع غــرب‬\n\n\n                                                                                      ‫‪462‬‬\n\f      ‫ســيهات مببلــغ قــدره مائتــا ألــف ريــال حيــث كنــت قــد حضــرت عقــد‬\n      ‫املبايعــة ثــم ألغيــت املبايعــة يف عــام ‪1431‬ه ـ يف اجتمــاع حضــره املتبايعــان‬\n      ‫وأنــا معهــم علــى أن تبقــى األرض ل‪...‬وأن يســترجع ‪...‬مــا دفعــه مــن مبالــغ‬\n      ‫وســمعت املدعــى عليــه ‪...‬هــذا احلاضــر وهــو يوافــق علــى إلغــاء املبايعــة‬\n      ‫وإعــادة املبالــغ ثــم تفرقــوا علــى ذلــك بعــد التراضــي عليــه ‪ ،‬هــذا مــا‬\n      ‫لــدي وأشــهد عليــه ‪ ،‬هــذا مــا شــهد بــه ‪ ،‬وبعــرض الشــاهد ومــا شــهد بــه‬\n      ‫علــى املدعــى عليــه قــال ‪ :‬أمــا الشــاهد فــا أعرفــه وأمــا مــا شــهد بــه مــن‬\n      ‫إلغــاء املبايعــة أو أنــي اســتلمت مــن املدعــي أي مبالــغ فهــذا غيــر صحيــح‬\n      ‫ا ‪ :‬إن الشــاهد لــم‬  ‫هــذا مــا قــرره ‪ ،‬ومبناقشــته تلفــظ أثنــاء كالمــه قائـ ً‬\n      ‫يحضــر اجتمــاع إلغــاء املبايعــة واإللغــاء كان شــفهي ًا ولــم يتــم حتريــر‬\n      ‫شــيء بذلــك ‪ ،‬هــذا مــا قالــه ‪ ،‬ثــم بإعــادة الــكالم عليــه بأنــك قلــت إنــه‬\n      ‫حصــل االتفــاق الشــفهي علــى اإللغــاء ولكنــه لــم يحــرر ‪ ،‬قــال ‪ :‬ال لــم‬\n      ‫يحصــل اتفــاق علــى اإللغــاء ‪ ،‬هــذا مــا قــرره ‪ ،‬وقــد الحظــت شــيئ ًا مــن‬\n      ‫االضطــراب يف كالم املدعــى عليــه ‪ ،‬ثــم إنــه يف جلســة أخــرى حضــر‬\n      ‫املدعــي أصالــة ‪ ...‬واملدعــى عليــه ‪ ،...‬وبســؤال املدعــي هــل لديــك زيــادة‬\n      ‫بينــة علــى دعــواك قــال ‪ :‬نعــم لــدي بينــة وســوف أحضرهــا يف اجللســة‬\n                                                                                ‫القادمــة‪،‬‬\n      ‫ثــم إنــه يف جلســة أخــرى حضــر املدعــي أصالــة ‪...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضــوره املدعــى عليــه ‪،...‬‬\n      ‫وبســؤال املدعــي عمــا وعــد بــه مــن زيــادة بينــة أحضــر للشــهادة وأدائهــا‬\n      ‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه‬\n      ‫شــهد بقولــه ‪ :‬أشــهد بــاهلل العظيــم بأنــه قبــل مــدة ال أتذكــر مقدارهــا‬\n      ‫بالضبــط ولكــن أظنهــا أكثــر مــن ســنة ونصــف تقريبـ ًا حضــر عنــدي‬\n\n\n‫‪463‬‬\n\f‫املدعــي ‪...‬واملدعــى عليــه ‪...‬هذيــن احلاضريــن وســمعتهما يتحــاوران فيمــا‬\n‫بينهمــا عــن مبايعــة علــى أرض ‪ ،‬ثــم قــام املدعــي ‪...‬هــذا احلاضــر بتســليم‬\n‫املدعــى عليــه ‪...‬هــذا احلاضــر مبلغـ ًَا نقديـ ًا قــدره خمســة عشــر ألــف ريــال‬\n‫يف ذلــك املجلــس حيــث قمــت بعــده ولكنــي ال أدري هــي مقابــل مــاذا ‪،‬‬\n‫وليــس لــدي أي شــهادة بخصــوص املبايعــة التــي متــت بينهمــا ‪ ،‬هــذا‬\n‫مالــدي مــن شــهادة وليــس لــدي زيــادة تفاصيــل ‪ ،‬وبســؤال املدعــي هــل‬\n‫لديــك زيــادة بينــة ‪ ،‬قــال ‪ :‬نعــم وســوف أحضرهــا يف اجللســة القادمــة ‪،‬‬\n‫ثــم إنــه يف جلســة أخــرى حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪...‬بصفتــه الوكيــل عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n‫الثانيــة برقــم ‪ 52171‬يف ‪1431/11/2‬ه ـ ولــم يحضــر املدعــى عليــه وال‬\n‫مــن ينــوب عنــه رغــم تبلغــه لشــخصه مبوعــد هــذه اجللســة حســب مــا هــو‬\n‫مبــن يف محضــر ضبــط اجللســة الســابقة ‪ ،‬وعليــه فقــد قــررت إكمــال‬\n‫نظــر الدعــوى غيابيـ ًا وبســؤال املدعــي وكالــة عمــا وعــد بــه موكلــه مــن‬\n‫زيــادة بينــة أبــرز صــور ًا خلمــس ورقــات ‪ ،‬األولــى تتضمــن مــا يلــي نصــه ‪:‬‬\n‫اتفــق كل مــن ‪... /‬حامــل بطاقــة احــوال رقــم ‪...‬طــرف أول مــع ‪...‬طــرف‬\n‫ثانــي بطاقــة أحــوال رقــم ‪...‬علــى ان يقــوم الطــرف األول باســتخراج صــك‬\n‫لــأرض الزراعيــة وإفــراغ األرض للطــرف الثانــي خــال ثالثــة أشــهر مــن‬\n‫تاريــخ اليــوم ‪1431/2/22‬ه ـ وهــذا املســتند يلغــي كافــة املكاتبــات‬\n‫التــي ســبقت هــذا االتفــاق وقــد اســتلم الطــرف األول مبلغـ ًا قــدره (‪)118‬‬\n‫الــف ريــال مــن قيمــة األرض ويف هــذا اليــوم اســتلم الطــرف األول‬\n‫(‪ )15000‬ريــال وبهــذا يكــون الطــرف األول قــد اســتلم (‪ )133‬ألــف‬\n‫ريــال مــن قيمــة األرض البالغــة (‪ )200000‬ريــال ويتعهــد الطــرف األول‬\n\n\n                                                                                        ‫‪464‬‬\n\f      ‫بإفــراغ الصــك يف املوعــد املذكــور ويتعهــد الطــرف الثانــي بســداد باقــي‬\n      ‫قيمــة األرض البالغــة (‪ )67000‬ريــال عنــد إفــراغ الصــك وبخالفــه يحــق‬\n      ‫للطــرف الثانــي املطالبــة باملبلــغ املدفــوع وهــو (‪ )133‬ألــف ريــال يف حالــة‬\n      ‫لــم يتــم إصــدار وإفــراغ الصــك طــرف أول‪... /‬بطاقــة ‪...‬توقيعــه طــرف‬\n      ‫ثانــي‪...... /‬توقيعــه شــاهد أول‪... /‬بطاقــة أحــوال ‪... /‬توقيعــه شــاهد ثانــي‬\n      ‫‪... /‬توقيعــه أه ـ والورقــة الثانيــة تتضمــن مــا يلــي نصــه ‪ :‬لقــد اســتلمت من‬\n      ‫الســيد ‪...‬احملتــرم مبلغـ ًا وقــدره عشــرة آال ف ريــال دفعــة مــن ثمــن أرض‬\n      ‫زراعيــة بســيحة اجلريعــة التابعــة للبــاد ســيهات واملســماة ‪ ...‬وســبقت‬\n      ‫هــذه الدفعــة دفعــة عربــون علــى شــراء األرض مــن قبــل املذكــور‬\n      ‫مقدارهــا عشــرة آالف ريــال نقــد ًا فيكــون مجمــوع املســتلم من املشــتري‬\n      ‫عشــرون ألــف ريــال وللبيــان أعطــي هــذا الســند ‪1428/8/3 .‬ه ـ املســتلم‬\n      ‫‪...‬توقيعــه ‪.‬أه ـ ‪ .‬والورقــة الثالثــة تتضمــن مــا يلــي نصــه ‪ :‬بيــان اســتالم‬\n      ‫عربــون مــن قيمــة قطعــة نخــل يف ســيحة اجلريعــة بســيهات ‪ .‬نعــم أنــا ‪...‬قــد‬\n      ‫اســتلمت مــن الســيد ‪... /‬مبلــغ قــدره عشــرة آالف ريــال نقــد ًا عربــون مــن‬\n      ‫أصــل مائتــن ألــف ريــال قيمــة قطعــة نخــل زراعيــة تقــع بســيحة اجلريعــة‬\n      ‫التابعــة للبــاد ســيهات املســماة ‪ ...‬يحدهــا شــما ًال نخــل ‪... ...‬وغربـ ًا نخــل‬\n      ‫‪...‬وجنوبـ ًا النخــل املســمى ‪ .........‬يفصــل بينهمــا طريــق يتجــه غربـ ًا ويتبــع‬\n      ‫‪ ...‬املذكــورة وشــرق ًا عــوارض ‪...‬و‪...‬و‪ ....‬وقــد اتفقــت مــع املشــتري‬\n      ‫املذكــور علــى أن أســتخرج لــه صــك بالنخــل املذكــور حــال اســتكمال‬\n      ‫دفعــه الثمــن وقــدره مائــة وتســعون ألــف ريــال وكذلــك تســليمه قطعــة‬\n      ‫النخــل املبــن بعاليــه بعــد ســنة واحــدة مــن تاريــخ هــذه الورقــة واهلل ولــي‬\n      ‫التوفيــق وهــو خيــر الشــاهدين وحــرر يف ‪1428/8/25‬ه ـ املشــتري ومــا‬\n      ‫نســب لــي صحيــح ‪...‬توقيعــه البائــع ‪... /‬توقيعــه ‪ .‬أه ـ ‪ .‬والورقــة الرابعــة‬\n\n\n‫‪465‬‬\n\f‫تتضمــن مــا يلــي نصــه ‪ :‬ســند اســتالم قــد مت أســتالم مبلــغ قــدره مائــة‬\n‫وخمســة وســتون الــف ريــال مــن املكــرم ‪... /‬وذلــك مــن قيمــة األرض‬\n‫املســماة ‪ ...‬الواقعــة بســيهات ســيحة اجلريعــة املباعــة عليــه مببلــغ مائتــي‬\n‫ريــال (‪ )200000‬ريــال مبــا لــأرض مــن حــد وعــد وتابــع والحــق ولبيــان‬\n‫مــا مت وذكــر أعــاه مت التوقيــع ‪1429/2/21 .‬ه ـ البائــع ‪... /‬توقيعه ‪ .‬أهـ‬\n‫‪ .‬والورقــة اخلامســة عبــارة عــن صــورة منــوذج إصــدار شــيك مصــريف مــن‬\n‫بنــك الريــاض وباالطــاع عليهــا وجدتهــا تتضمــن قيــام ‪...‬بإصــدار شــيك‬\n‫مصــريف برقــم ‪ 2860732‬وتاريــخ ‪2008/1/9‬م ألمــر املســتفيد ‪...‬مببلــغ‬\n‫قــدره ثمانــون ألــف ريــال أه ـ ‪ .‬ثــم إنــه يف جلســة أخــرى حضــر املدعــي‬\n‫وكالــة ‪...‬وحضــر حلضــوره املدعــي أصالــة ‪ ، ...‬وبعــرض األوراق اخلمــس‬\n‫املشــار إليهــا يف اجللســة الســابقة علــى املدعــى عليــه قــال ‪ :‬األوراق األربــع‬\n‫األولــى حــررت صحيحــة والتوقيــع املــدون فيهــا هــو توقيعــي ولكــن‬\n‫الورقــة األولــى هــي اتفــاق لــم يتــم تنفيــذه حيــث إنــي أعطيــت مــوكل‬\n‫املدعــي خمســن ألــف ريــال ليقــوم باســتخراج صــك حجــة اســتحكام‬\n‫لــأرض محــل النــزاع ولكنــه لــم يقــم بذلــك ‪ ،‬وقــد تضمنــت الورقــة‬\n‫األولــى أنهــا تلغــي كل مــا ســبقها مــن أوراق واألوراق التــي قبلهــا توجــد‬\n‫أصولهــا لــدي أنــا شــخصي ًا وأمــا الورقــة اخلامســة الصــادرة مــن بنــك ‪...‬‬\n‫فإنهــا غيــر صحيحــة ولــم يصلنــي مــن مــوكل املدعــي املبلــغ املشــار إليــه‬\n‫فيهــا ‪ ،‬هــذا مــا قــرره ‪ ،‬ثــم تقــدم املدعــي وكالــة وأبــرز أصــل الورقــة‬\n‫األولــى وبعرضهــا علــى املدعــى عليــه صــادق عليهــا وقــال ‪ :‬الــذي لــدي‬\n‫هــو أصــول األوراق الثانيــة والثالثــة والرابعــة فقــط ‪ ،‬وبســؤال املدعــي‬\n‫وكالــة هــل لديــك زيــادة بينــة علــى دعــواك قــال ‪ :‬ليــس لــدي بينــة غيــر‬\n‫مــا ذكــرت ‪ ،‬هــذا مــا قــرره ‪ ،‬وعنــد وصــول القضيــة لهــذا احلــد رفعــت‬\n\n\n                                                                                        ‫‪466‬‬\n\f      ‫اجللســة للكتابــة ملؤسســة النقــد لالستفســار عــن صحــة الورقــة اخلامســة‬\n      ‫وهــل اســتلم املدعــى عليــه املبلــغ املذكــور فيهــا ‪ ،‬ثــم إنــه يف جلســة‬\n      ‫أخــرى حضــر املدعــي وكالــة ‪...‬واملدعــى عليــه ‪ ،...‬وكانــت قــد جــرت‬\n      ‫منــا الكتابــة ملؤسســة النقــد العربــي الســعودي يف الدمــام بخطابنــا رقــم‬\n      ‫‪ 33733534‬وتاريــخ ‪1433/4/18‬ه ـ لإلفــادة عــن املدعــى عليــه هــل‬\n      ‫اســتلم قيمــة الشــيك املســحوب علــى بنــك ‪...‬فــرع القطيــف برقــم‬\n      ‫‪ 2860732‬يف ‪2008/1/9‬م فوردنــا منهــم اجلــواب رقــم ‪ 22/4032‬ش‬\n      ‫‪ 2143/‬وتاريــخ ‪1433/6/14‬ه ـ املتضمــن مــا نصــه ‪ :‬نــود إفــادة‬\n      ‫ســعادتكم بــأن املؤسســة قامــت مبخاطبــة بنــك الريــاض بخصــوص‬\n      ‫املوضــوع أعــاه وتلقــت إجابــة البنــك ومفادهــا أنــه مت خصــم قيمــة‬\n      ‫الشــيك مــن احلســاب اجلــاري رقــم (‪ )...‬واخلــاص باملدعــو ‪...‬بتاريــخ‬\n      ‫‪2008/1/13‬م لصالــح ‪...‬ومت تقدميــه إلــى غرفــة مقاصــة الدمــام عــن‬\n      ‫طريــق البنــك الســعودي البريطانــي ( مرفــق نســخة الشــيك بعــد الصــرف‬\n      ‫) وبنــاء عليــه قامــت املؤسســة مبخاطبــة البنــك الســعودي البريطانــي‬\n      ‫بخصــوص نفــس املوضــوع وأفــاد البنــك بــأن الشــيك مت إيداعــه يف‬\n      ‫حســاب املســتفيد ‪...‬رقم (‪ )...‬بتاريخ ‪2008/1/12‬م أهـ‪ .‬ثم إنه يف جلســة‬\n      ‫أخــرى حضــر املدعــي وكالــة ‪...‬واملدعــى عليــه ‪ ،...‬وبســؤال املدعــي‬\n      ‫وكالــة ميــن موكلــه علــى صحــة دعــواه ؛ قــال ‪ :‬إن موكلــي مســتعد‬\n      ‫بــأداء اليمــن علــى صحــة دعــواه ‪ ،‬ثــم إنــه يف جلســة أخــرى حضر املدعي‬\n      ‫ا ‪ :‬إن صحــة‬   ‫أصالــة ‪ ...‬واملدعــى عليــه أصالــة ‪ ،...‬وقــرر املدعــي قائ ـ ً‬\n      ‫املبلــغ الــذي ســلمته للمدعــى عليــه مــن قيمــة املبيــع هــو مائــة وثالثــة‬\n      ‫وثمانــون ألــف ريــال وبعــد االتفــاق علــى إلغــاء املبايعــة أرجــع لــي املدعــى‬\n      ‫عليــه خمســن ألــف ريــال وتبقــى يف ذمتــه بعــد ذلــك املبلــغ املدعــى بــه‬\n\n\n‫‪467‬‬\n\f‫وقــدره مائــة وثالثــة وثالثــون ألــف ريــال وهــو مــا أطالبــه بــه ‪ ،‬هــذا مــا‬\n‫قــرره ‪ ،‬وبطلــب تعديــل شــاهد املدعــي ‪...‬أحضــر املدعــي كال مــن‬\n‫‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬و ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤالهما شــهدا بثقــة وعدالــة الشــاهد‬\n‫‪ ...‬وأنــه مرضــي الشــهادة ‪ ،‬وبطلــب اليمــن مــن املدعــي علــى صحة دعواه‬\n‫ا ‪ :‬أقســم بــاهلل العظيــم أننــي أنــا املدعــي‬  ‫اســتعد بأدائهــا ثــم حلــف قائـ ً‬\n‫‪...‬واملدعــى عليــه ‪ ......‬قــد اتفقنــا وتراضينــا علــى إلغــاء املبايعــة التــي متــت‬\n‫بيننــا علــى األرض الزراعيــة املســماة ‪ ....‬الواقعــة بســيحة اجلريعــة املشــار‬\n‫إليهــا يف الدعــوى وعلــى أن يعيــد لــي املدعــى عليــه مائــة وثالثــة وثمانــن‬\n‫ألــف ريــال ‪ ،‬وأن املدعــى عليــه لــم يســدد لــي مــن هــذا املبلــغ الــذي اتفقنــا‬\n‫علــى ارجاعــه ســوى خمســن ألــف ريــال وأنــه قــد تبقــى لــي يف ذمــة‬\n‫املدعــى عليــه مبلغ ـ ًا قــدره مائــة وثالثــة وثالثــون ألــف ريــال لــم يســدده‬\n‫حتــى اآلن ‪ ،‬واهلل العظيــم أه ـ ‪ .‬فبنــاء علــى ما تقدم من الدعوى واإلجابة‬\n‫ونظــر ًا ملــا ورد يف شــهادة الشــاهد ‪...‬املعــدل التعديــل الشــرعي والتــي‬\n‫تضمنــت الشــهادة علــى اتفــاق املتداعيــن علــى إلغــاء املبايعــة وســماع‬\n‫الشــاهد للمدعــى عليــه وهــو يوافــق علــى إلغــاء املبايعــة وإعــادة املبلــغ‬\n‫للمدعــي ‪ ،‬وملــا قــرره املدعــى عليــه بعــد الشــهادة مــن أن الشــاهد لــم‬\n‫يحضــر اجتمــاع إلغــاء املبايعــة وأن اإللغــاء كان شــفهي ًا ‪ ،‬وألن يف ذلــك‬\n‫إقــرار منــه بحصــول اإللغــاء للمبايعــة ‪ ،‬وملــا ورد يف االوراق والســندات‬\n‫التــي قدمهــا املدعــي وصــادق املدعــى عليــه علــى صحتهــا وملــا ورد يف‬\n‫جــواب مؤسســة النقــد عــن الورقــة اخلامســة وملــا قــرره املدعــي أخيــر ًا ‪،‬‬\n‫وألن املدعــي قــد أدى اليمــن كمــا طلبــت منــه وملــا قــرره أكثــر أهــل‬\n‫العلــم مــن ثبــوت املــال ملدعيــه بشــاهد وميــن وهــو رأي اخللفــاء الراشــدين‬\n\n\n                                                                                            ‫‪468‬‬\n\f      ‫األربعة والفقهاء الســبعة واحلنابلة ومالك والشــافعي ‪ .‬املغني (‪)130/14‬‬\n      ‫ملــا رواه ســهيل عــن أبيــه عــن أبــي هريــرة رضــي اهلل عنــه قــال ‪ :‬قضــى‬\n      ‫رســول اهلل صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد الواحــد ‪ .‬رواه‬\n      ‫ســعيد بــن منصــور يف ســننه واألئمــة مــن أهــل الســن واملســانيد ‪ .‬لذلــك‬\n      ‫كلــه فقــد حكمــت علــى املدعــى عليــه ‪...‬بــأن يدفــع للمدعــي ‪...‬مبلغ ـ ًا‬\n      ‫قــدره مائــة وثالثــة وثالثــون ألــف ريــال ‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه قــرر عــدم القناعــة فأفهمتــه بــأن عليــه مراجعتنــا يــوم الســبت‬\n      ‫املوافــق ‪1434/3/28‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي‬\n      ‫اعتراضــه عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ موعــد االســتالم إن لــم‬\n      ‫يقــدم اعتراضــه خاللهــا يســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n      ‫القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n      ‫آله وصحبه وســلم حرر يف ‪1434/3/25‬هـ ‪ .‬تظهيرات الدائرة احلقوقية‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية ‪ ،‬احلمــد هلل وحــده‬\n      ‫وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34172977‬وتاريــخ‬\n      ‫‪1434/3/28‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪... /‬‬\n      ‫واصدرنــا القــرار رقــم ‪ /34277832‬ق‪ /1‬أ وتاريــخ ‪1434/7/24‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬قاضــي اســتئناف ‪ . ...‬ختمــه وتوقيعــه‬\n      ‫‪ .‬قاضــي اســتئناف د‪ .... .‬ختمــه وتوقيعــه ‪ .‬رئيــس الدائــرة ‪ ....‬ختمــه‬\n      ‫وتوقيعــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                       ‫وسلم ‪ .‬حرر يف ‪1434/8/9‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n\n\n‫‪469‬‬\n\f‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم ‪32447278‬‬\n‫وتاريــخ ‪1434/5/11‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341183778‬‬\n‫وتاريــخ ‪1434/5/14‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪ ... /‬املسـ ّـجل برقــم ‪ 34172977‬وتاريــخ‬\n‫‪1434/3/28‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة حقوقيــة وقــد‬\n‫تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/7/24‬ه ـ ‪ ،‬واهلل ولــي‬\n                                                               ‫التوفيــق ‪.‬‬\n\n\n\n\n                                                                             ‫‪470‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":460,"source_page_end":470,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d35d9a4125cec12c3c187ce94106dbe4dbdc78ce005b03b8225a507b82a825ad","normalized_text_hash":"568463c0a310d98dfdd427e5a10bf007c8d2f4c60f6ce5635e6a8b0b04ca3fbc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p460-34172977"},{"id":"6aa73c67-a463-524b-a3eb-4b1725fa6b6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -بيع بيت -ادعاء الغن يف البيع -املطالبة بإعادة البيت مقابل رد الثمن -البيعان باخليار مالم يتفرقا -صرف النظر عن","document_number":"34174457","case_number":"3453926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/29","year":"1434","subject":"عقار -بيع بيت -ادعاء الغن يف البيع -املطالبة بإعادة البيت مقابل رد الثمن -البيعان باخليار مالم يتفرقا -صرف النظر عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34174457 :‬تاريخه ‪1434/3/29:‬هـ‬\n                          ‫رقم الدعوى ‪3453926 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34242731:‬تاريخه‪1434/06/17:‬هـ‬\n\n\n      ‫عقــار‪ -‬بيــع بيــت ‪ -‬ادعــاء الغــن يف البيــع ‪ -‬املطالبــة بإعــادة البيــت‬\n      ‫مقابــل رد الثمــن ‪ -‬البيعــان باخليــار مالــم يتفرقــا ‪ -‬صــرف النظــر عــن‬\n                                                                   ‫دعــوى الغــن ‪.‬‬\n\n\n\n                   ‫قوله صلى اهلل عليه وسلم ( البيعان باخليار مالم يتفرقا )‬\n\n\n\n\n      ‫ادعــى املدعــى بأنــه بــاع بيتــه علــى املدعــى عليــه قبــل أربــع ســنوات تقريبـ ًا‬\n      ‫بثمــن قــدره ســتمائة الــف ريــال اســتلمها‪ -‬قرر املدعى أنــه ال يعرف أثمان‬\n      ‫العقــار وعندمــا رغــب بشــراء بيــت لــم يجــد إال مبــا يزيــد علــى مليــون‬\n      ‫ريــال‪ -‬طلــب املدعــى إلــزام املدعــى عليــه بإعــادة البيــت لــه واســتعداده‬\n      ‫بإعــادة الثمــن للمدعــى عليــه‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‬\n      ‫وأن شــراءه لهــذا البيــت كان قبــل خمــس ســنوات وهــو ســعر املثــل يف‬\n      ‫وقتــه وأن املدعــى عــرض البيــت عــن طريــق مكتــب عقــار وقــد باعــه‬\n      ‫املدعــى بثمــن أقــل مــن الثمــن الذي اشــتراه بــه إال أن املشــتري األول ألغى‬\n      ‫الشــراء‪ -‬صــادق املدعــى علــى أن البيــت مت عرضــه عــن طريــق مكتــب‬\n      ‫عقــار وتقــدم لشــرائه عــدة أشــخاص واشــتراه شــخص بنفــس الثمــن ثــم‬\n      ‫تراجــع عــن الشــراء ثــم اشــتراه املدعــى عليــه بالثمــن املذكــور‪ -‬حيــث‬\n\n‫‪471‬‬\n\f‫أن تغيــر االســعار يف الوقــت احلاضــر ليــس مســوغ ًا للمدعــى يف املطالبــة‬\n‫بإلغــاء البيــع وألن عقــد البيــع عقــد الزم ولقولــه صلــى اهلل عليــه وســلم‬\n‫( البيعــان باخليــار مالــم يتفرقــا ) لــذا صــدر احلكــم بــرد دعــوى املدعــى‬\n‫جتــاه املدعــى عليــه‪ -‬اعتــرض املدعــى علــى احلكــم‪ -‬صــدق احلكــم مــن‬\n                                                       ‫محكمــة االســتئناف‬\n\n\n\n‫العامــة‬\n    ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة‬\n‫باألحســاء حضــر املدعــي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬كمــا حضــر املدعــى عليــه ‪ ...‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬وقــال املدعــي يف حتريــر دعــواه إننــي قــد بعــت علــى املدعــى عليــه‬\n‫هــذا احلاضــر بيتــي الواقــع يف حــي ‪...‬باملبــرز باألحســاء والصــادر فيــه‬\n‫الصــك رقــم ‪ 2/1193‬يف ‪1403/8/13‬ه ـ مــن كتابــة عدل املبرز وكان‬\n‫البيــع قبــل أربــع ســنوات تقريبــا بثمــن وقــدره ســتمائة ألف ريال اســتلمتها‬\n‫كاملــة مــن املدعــى عليــه وأنــا ال أعــرف أثمــان العقــارات وعندمــا رغبت‬\n‫اآلن شــراء بيــت لــم أجــد إال مبــا يزيــد علــى مليــون ريــال لــذا فإنــي أطلــب‬\n‫إلــزام املدعــى عليــه بإعــادة هــذا البيــت لــي وال مانــع لــدي مــن إعــادة‬\n‫الثمــن لــه هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره‬\n‫املدعــي يف دعــواه صحيــح فقــد اشــتريت مــن املدعــي البيــت محــل‬\n‫الدعــوى بالثمــن الــذي ذكــر ولكــن ذلــك كان قبــل خمــس ســنوات‬\n‫وســلمته الثمــن وهــذا ثمنــه يف الســوق يف ذلــك الوقــت وقــد عرضــه‬\n‫املدعــي لــدى مكتــب ‪ ...‬باملبــرز كمــا أنــي أضيــف أن املدعــي قــد باعــه‬\n‫بأقــل مــن هــذا الثمــن علــى شــخص قبلــي ومت إلغــاء البيــع واشــتريته أنــا‬\n\n                                                                                         ‫‪472‬‬\n\f      ‫بالثمــن املذكــور واملدعــي مســتأجر منــي هــذا البيــت وال زال يســكن‬\n      ‫فيــه وال أوافــق علــى إعادتــه لــه هكــذا أجــاب وبعــرض ذلــك علــى‬\n      ‫املدعــي قــال صحيــح أننــي عرضــت البيــت محــل الدعــوى لــدى مكتــب‬\n      ‫‪ ...‬وتقــدم لشــرائه عــدة أشــخاص ثــم اشــتراه شــخص يدعــى ‪...‬مببلــغ‬\n      ‫ســتمائة ألــف ريــال ثــم تراجــع واشــتراه بعــد ذلــك املدعــى عليــه هكــذا‬\n      ‫أجــاب وأبــرز املدعــى عليــه صــك البيــت محــل الدعــوى املذكــور رقمــه‬\n      ‫وتاريخــه وفيــه مت التهميــش عليــه بانتقــال ملكيتــه إلــى املدعــى عليــه‬\n      ‫بتاريــخ ‪1433/3/23‬ه ـ وقــال املدعــى عليــه إن البيــت محــل الدعــوى‬\n      ‫كان مرهــون لصالــح صنــدوق التنميــة العقــاري وبعــد فــك الرهــن مت‬\n      ‫اإلفــراغ لــي مــن قبــل املدعــى عليــه وهــذا هــو الــذي أخــر عمليــة اإلفــراغ‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث قــرر املدعــي أنــه‬\n      ‫بــاع البيــت محــل الدعــوى قبــل قرابــة أربــع ســنوات واســتلم ثمنــه وأنــه‬\n      ‫عرضــه لــدى مكتــب عقــاري ومتــت املزايــدة عليــه مــن عــدة أشــخاص‬\n      ‫وأنــه مت شــرائه مــن قبــل شــخص آخــر قبــل املدعــى عليــه بالثمــن نفســه‬\n      ‫املذكــور يف الدعــوى ومبــا أن تغيــر األســعار يف الوقــت احلاضــر ليــس‬\n      ‫مســوغ ًا للمدعــي يف املطالبــة بإلغــاء البيــع ومبــا أن البيــع ملــزم للطرفــن‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ( البيعــان باخليــار مــا لــم يتفرقــا ) لــذا فلــم‬\n      ‫يثبــت لــدي حــق للمدعــي فيمــا يطالــب بــه ورددت دعــواه جتــاه املدعــى‬\n      ‫عليــه وبذلــك حكمــت وبعرضــه عليهمــا قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم فيمــا قــرر املدعــي عــدم قناعتــه باحلكــم وأفهمتــه باملراجعــة‬\n      ‫يف يــوم الســبت املوافــق ‪1434/3/28‬ه ـ الســتالم نســخه احلكــم وتقــدمي‬\n      ‫االعتــراض عليــه خــال ثالثــن يومــا وإال ســقط حقــه يف االعتــراض‬\n      ‫واكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪473‬‬\n\f         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/6/25‬ه ـ وقــد وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫الصــادر مــن الدائــرة احلقوقيــة األولــى برقــم ‪ / 34242731‬ق ‪ / 1‬أ‬\n‫وتاريــخ ‪1434/6/17‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫لــذا جــرى إحلاقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                      ‫آلــه وصحبــه وســلم ‪0‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامة مبحافظة األحســاء برقــم ‪34/267263‬‬\n‫وتاريــخ ‪1434/5/6‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341156999‬‬\n‫وتاريــخ ‪1434/5/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪... /‬املســجل برقــم ‪ 34174457‬وتاريــخ‬\n‫‪1434/3/29‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة حقوقيــة وقــد‬\n‫تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n‫قررنــا‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة ّ‬\n‫املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/6/14‬ه ـ ‪ ،‬واهلل ولــي‬\n                                                                    ‫التوفيــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪474‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":471,"source_page_end":474,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"21576dfacfc481d6c5b033691dda115b5d5c219f1ba9c42918781327a2992268","normalized_text_hash":"57418556b3c526125a195cd4af86a07c6d8cb28801de40eddc5133761dd42092","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p471-34174457"},{"id":"aac39ffb-e7a4-5e8e-a190-f2a8e72e8a44","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء قطعة أرض بدون صك -طلب فسخ عقد البيع ورد مبلغ الشراء وتكاليف البناء لظهور مالك لأرض غير البائع املدعى عليه -عدم انعقاد البيع -شرط صحة البيع متام ال ملك -املفرط أولى باخلسارة -إلزام املدعى عليه برد املبلغ الذي استلمه من املدعى وصرف النظر عن باقي الطلبات .- -1قول النبي صلي اهلل عليه وسلم ( على اليد ما أخذت حتى","document_number":"34185173","case_number":"32397739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/10","year":"1434","subject":"عقار -شراء قطعة أرض بدون صك -طلب فسخ عقد البيع ورد مبلغ الشراء وتكاليف البناء لظهور مالك لأرض غير البائع املدعى عليه -عدم انعقاد البيع -شرط صحة البيع متام ال ملك -املفرط أولى باخلسارة -إلزام املدعى عليه برد املبلغ الذي استلمه من املدعى وصرف النظر عن باقي الطلبات .- -1قول النبي صلي اهلل عليه وسلم ( على اليد ما أخذت حتى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34185173 :‬تاريخه ‪1434/04/10 :‬هـ‬\n                         ‫رقم الدعوى ‪32397739 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‬\n              ‫‪ 341914127:‬تاريخه‪1434/09/09 :‬هـ‬\n\n\n       ‫عقــار‪ -‬شــراء قطعــة أرض بــدون صــك‪ -‬طلــب فســخ عقــد البيــع ورد‬\n       ‫مبلــغ الشــراء وتكاليــف البنــاء لظهــور مالــك لــأرض غيــر البائــع‬\n       ‫املدعــى عليــه ‪ -‬عــدم انعقــاد البيــع ‪ -‬شــرط صحــة البيــع متــام ال ــملك‬\n       ‫‪ -‬املفــرط أولــى باخلســارة ‪ -‬إلــزام املدعــى عليــه بــرد املبلغ الذي اســتلمه‬\n                              ‫مــن املدعــى وصــرف النظــر عــن باقــي الطلبــات ‪.-‬‬\n\n\n\n\n       ‫‪ -1‬قــول النبــي صلــي اهلل عليــه وســلم ( علــى اليــد مــا أخــذت حتــى‬\n                                                                         ‫تؤديــه )‬\n                                              ‫‪ -2‬قاعدة املفرط أولى باخلسارة‬\n                 ‫‪ -3‬من شرط صحة البيع ثبوت ملك البائع للعني املباعة‬\n\n\n\n\n       ‫ادعــى املدعــى بأنــه اشــترى قطعــه أرض بــدون صــك مــن املدعــى عليــه‬\n       ‫وســلم ثمنهــا للمدعــى عليــه وقــام بتســويرها ثــم ظهــر لــأرض مالــك‬\n       ‫آخــر وهــو ابــن عــم املدعــى عليــه‪ -‬طلــب املدعــى إلــزام املدعــى عليــه‬\n       ‫بإعــادة الثمــن وتكاليــف التســوية والتســوير‪ -‬أقــر املدعــى عليــه بالبيــع‬\n       ‫واســتالم الثمــن املذكــور وأمــا التســوية والتســوير فقــرر أنــه ال يعلــم‬\n       ‫عــن ذلــك كمــا قــرر املدعــى عليــه أن األرض تخصــه وال تخــص ابــن‬\n\n‫‪475‬‬\n\f‫عمــه املذكــور وأنــه مســتعد باملدافعــة عــن املدعــى جتــاه مــن يعترضــه‪-‬‬\n‫حضــر شــيخ القبيلــة وقــرر أن األرض تخــص ابــن عــم املدعــى عليــه وال‬\n‫تخــص املدعــى عليــه‪ -‬قــرر املدعــى عليــه وكالــه بــأن شــيخ القبيلــة‬\n‫خصــم ملوكلــه‪ -‬حيــث مــن شــرط صحــة البيــع ثبــوت ملــك البائــع للعــن‬\n‫املباعــة ولــم يتحقــق هــذا الشــرط وملعرفــه املدعــى بــأن األرض املشــتراة‬\n‫بــدون صــك لــذا صــدر احلكــم بعــدم انعقــاد البيــع لفــوات شــرط صحتــه‬\n‫والــزام املدعــى عليــه أصالــه بدفــع املبلــغ الــذى اســتلمه للمدعــى وصــرف‬\n‫النظــر عــن باقــي طلبــات املدعــى لدخولــه يف هــذا العقــد علــى بينــه‬\n‫واملفــرط أولــى باخلســارة‪ -‬اقتنــع املدعــى باحلكــم ولــم يقتنــع املدعــى‬\n                        ‫عليــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائف‪/‬املســاعد برقــم ‪ 32397739‬وتاريــخ ‪1432/09/07‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 321159884‬وتاريــخ ‪ 1432/09/07‬ه ـ‬\n‫ففــي يــوم األربعــاء املوافــق‪ 1432/10/30‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09 : 25‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬و حضــر حلضــوره ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫ا عــن املدعــى عليــه ‪...‬مبوجــب الوكالــة رقــم ‪ 1096‬يف‬       ‫رقــم ‪...‬وكي ـ ً‬\n‫‪1433/1/4‬ه ـ املتضمنــة حقــه يف حضــور اجللســات واملدافعــة واملرافعــة‬\n‫واإلقــرار واإلنــكار وطلــب األميــان والصلــح والتنــازل أ‪0‬ه ـ وبســؤال‬\n‫املدعــي عمــا لديــه قــال لقــد اشــتريت قطعــة أرض بالرميــدة القطعــة‬\n\n                                                                                   ‫‪476‬‬\n\f      ‫رقــم ج ‪ 565‬بــدون صــك مــن املدعــى عليــه أصالــة ‪...‬مببلــغ وقــدره أربعــة‬\n      ‫وثالثــون ألــف ريــال وقمــت بتســويرها وتســويتها وقــد كلفتنــي مــا‬\n      ‫يقــارب خمســة وعشــرون ألــف ريــال ولــم أتقــدم باســتحكام ثــم ظهــر أن‬\n      ‫لــأرض مالــك آخــر غيــر املدعــى عليــه البائــع وهــو ابــن عمــه ‪...‬لــذا أطلب‬\n      ‫فســخ البيــع وإلــزام املدعــى عليــه بإرجــاع مبلــغ قــدره تســعة وخمســون‬\n      ‫ألــف ريــال لــي وبطلــب اجلــواب مــن املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي يف دعــواه مــن الشــراء وقيمتــه وتســوية األرض فهــذا صحيــح‬\n      ‫وقــد مضــى علــى ذلــك ســنه دون معــارض ثــم حصلــت معارضــة ابــن عــم‬\n      ‫موكلــي ‪...‬مدعيــا أن هــذه األرض مــن نصيبــه لــذا أطلــب إدخــال شــيخ‬\n      ‫القبيلــة ‪...‬و‪...‬لســماع مــا لديهــم هــذه إجابتــي ثــم أنــه يف يــوم األربعــاء‬\n      ‫املوافــق‪ 1434/02/20‬ه ـ افتتحــت اجللســة الســاعة التاســعة لــدي أنــا‬\n      ‫‪...‬القاضــي يف احملكمــة العامــة بالطائــف والقائــم بعمــل املكتــب‬\n      ‫القضائــي الرابــع عشــر وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n      ‫وال مــن ميثلــه بوكالــة شــرعية كمــا حضــر ‪...‬ســعودي اجلنســية ســجله‬\n      ‫املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه قــال ان القطعــة رقــم ‪ 565‬ج الواقعــة‬\n      ‫يف الرميــدة تعــود ملكيتهــا إلــى ‪ ...‬وليســت ل‪...‬هــذه إجابتــي ثــم أبــرز‬\n      ‫البيــان اخلــاص ب‪...‬والبيــان اخلــاص ب‪......‬جــرى إرفاقهمــا باملعاملــة ثــم‬\n      ‫أنــه يف يــوم األربعــاء املوافــق‪ 1434/04/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة لــدي أنــا ‪...‬مســاعد رئيــس احملكمــة العامــة بالطائــف والقائــم‬\n      ‫بعمــل املكتــب القضائــي الرابــع عشــر وفيهــا حضــر املدعــي وحضــر‬\n      ‫حلضــوره ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وكيــا‬\n      ‫عــن ‪...‬بالوكالــة رقــم ‪ 3429608‬يف ‪1434/1/10‬ه ـ الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بالطائــف واملتضمنــة حقــه يف ســماع الدعــاوي‬\n\n\n‫‪477‬‬\n\f‫والــرد عليهــا واملرافعــة واملدافعــة واإلقــرار واإلنــكار وقبــول األحــكام‬\n‫ونفيهــا أ‪.‬ه ـ وبعــرض مــا جــاء يف إفــادة شــيخ القبيلــة احلاضــر يف اجللســة‬\n‫املاضيــة علــى الطرفــن قــال املدعــي هــذا هــو الواقــع وأنــا مقتنــع مبــا‬\n‫جــاء بإفادتــه أمــا املدعــى عليــه وكالــة فأجــاب بقولــه إن شــيخ القبيلــة‬\n‫خصــم ملوكلــي وال أرضــى مبــا ذكــر واملدعــي إذا جــاء مــن يخاصمــه يف‬\n‫األرض فنحــن ندفــع عنــه هــذه إجابتــي ثــم ســألت املدعــى عليــه وكالــة‬\n‫هــل موكلــك ميلــك هــذه األرض بصــك شــرعي مســتكمل اإلجــراءات‬\n‫النظاميــة فأجــاب بقولــه ال بــل املنطقــة معروفــة بأنهــا مــن أمــاك ‪....‬‬\n‫القدميــة واألرض بيــد املدعــي وقــد ســورها وهــي حتــت تصرفــه هكــذا‬\n‫أجــاب ثــم أضــاف املدعــي بقولــه أطلــب إلــزام املدعــى عليــه أصالــة‬\n‫بدفــع مبلغــا قــدره ( ‪ )66040‬ســت وســتون ألفــا وأربعــون ريــال عبــارة‬\n‫عمــا يلــي شــراء أرض أربعــة وثالثــون ألــف ريــال وحتويــش األرض اثنــا‬\n‫عشــر ألفــا وخمســمائة ريــال وتكســير حصــى خمســة عشــر ألــف ريــال‬\n‫ومشــتروات متناثــرة ألــف وأربعــون ريــاال وبــاب عــدد ‪ 2‬للحــوش ثالثــة‬\n‫آالف ريــال ومصاريــف شــيوالت خمســمائة ريــال واملجمــوع ســتة وســتون‬\n‫ألفــا وأربعــون ريــاال لــذا أطلــب فســخ البيــع وإلزامــه بجميــع التكاليــف‬\n‫هــذا تصحيــح دعــواي وبعرضهــا علــى املدعــى عليــه وكالــة قــال األرض‬\n‫بيــده وســورها وال نــدري عــن التكاليــف التــي تكبدهــا ســوى قيمــة‬\n‫الشــراء أربعــة وثالثــون ألــف ريــال اســتلمها موكلــي هــذه إجابتــي وبعــد‬\n‫ســماع الدعــوى واإلجابــة وألن مــن شــرط صحــة البيــع ثبــوت ملــك البائــع‬\n‫للعــن املباعــة ولــم يتحقــق هــذا الثبــوت يف هــذه الدعــوى وملعرفــة املدعــي‬\n‫بــأن األرض التــي اشــتراها بــدون صــك ولعمــوم قولــه صلــى اهلل عليــه‬\n‫وســلم ( علــى اليــد مــا أخــذت حتــى تؤديــه ) جلميــع مــا تقــدم فقــد ثبــت‬\n\n\n                                                                                     ‫‪478‬‬\n\f      ‫لــدي عــدم انعقــاد هــذا البيــع لفــوات شــرط صحتــه وألزمــت املدعــى‬\n      ‫عليــه أصالــة بدفــع مبلــغ قــدره أربعــة وثالثــون ألــف ريــال التــي اســتلمها‬\n      ‫مــن املدعــي وصرفــت النظــر عــن باقــي طلبــات املدعــي لدخولــه يف‬\n      ‫هــذا العقــد علــى بينــة واملفــرط أولــى باخلســارة وبعرضــه علــى الطرفــن‬\n      ‫قــرر املدعــي القناعــة بــه وقــرر املدعــى عليــه وكالــة عــدم القناعــة بــه‬\n      ‫فأفهمتــه باملراجعــة يــوم األحــد ‪1434/4/14‬ه ـ الســتالم نســخة مــن‬\n      ‫احلكــم إلبــداء اعتراضــه عليــه خــال ثالثــن يومــا مــن تاريــخ اســتالمه‬\n      ‫نســخة احلكــم فــإن مضــت املــدة دون تقــدمي الالئحــة االعتراضيــة ســقط‬\n      ‫حقــه يف االعتــراض واكتســب احلكــم القطعيــة وذلــك اســتنادا للمــواد‬\n      ‫رقــم ‪ 176‬و ‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ففهم‬\n      ‫ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                               ‫وســلم حــرر يف ‪1434/4/10‬ه ـ الســاعة العاشــرة ‪.‬‬\n      ‫ثــم إنــه يف يــوم اخلميــس ‪1434/9/17‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n      ‫عشــر لــدي أنــا ‪...‬وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيــس محكمــة االســتئناف مبكــة املكرمــة املكلــف برقــم‬\n      ‫‪ 341914127‬يف ‪1434/9/9‬ه ـ مرفق ـ ًا بــه قــرار الدائــرة احلقوقيــة‬\n      ‫الثالثــة رقــم ‪ 34306014‬يف ‪1434/8/25‬ه ـ املــدون علــى ظهــر الصــك‬\n      ‫واملتضمــن ( وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت باألكثريــة املوافقــة علــى احلكــم )أ‪.‬ه ـ وأمــرت بإحلاقــه بصكــه‬\n      ‫وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪ 1434/9/17‬ه ـ ‪.‬‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n\n\n‫‪479‬‬\n\f‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n‫الشي ــخ ‪ ...‬مســاعد رئيــس احملكمــة العامــة بالطائــف واملســجل بعــدد‬\n‫‪ 34185173‬وتــاري ــخ ‪1434/4/10‬هـ ـ املتضمــن دعــوى ‪...‬ضــد ‪ ......‬يف‬\n                                  ‫مبلــغ مالــي احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــرر‬\n‫باألكثريــة املـ ــوافقـ ـ ـ ــة علــى احلكــم ‪.‬وبــاهلل تعالــى التوفيــق ‪.‬وصل ــى اهلل‬\n ‫عل ــى نبي ــنا محم ــد وعل ــى آل ــه وصحب ــه وس ــلم ‪،،،،،،،،،،،،،،‬‬\n\n\n\n\n                                                                                           ‫‪480‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":475,"source_page_end":480,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed9286222561fc2cdcdf7dcf54c82f26c446beec54ddfc7d13ce2c8257f45641","normalized_text_hash":"83ed22926f6ae819c931938d6e8ff39f9edd5e9f6d7be51f0eb3a869555fc374","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p475-34185173"},{"id":"378fb4b2-c117-54de-ba89-430d1100def3","document_type":"judgment","category":"judicial","subcategory":"general","title":"إثبات ملكية عقار -رهن -إفراغ صوري -عدم قبول شهادة عمودي النسب لبعضهم البعض وقبولها عليهم -حكم بانتقال ملكية عقار -التثبت يف حقوق القصر -تعديل الشهود -إقرار الورثة بالصورية -قضاء بانتقال امللكية.","document_number":"34262424","case_number":"34259555","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/09","year":"1434","subject":"إثبات ملكية عقار -رهن -إفراغ صوري -عدم قبول شهادة عمودي النسب لبعضهم البعض وقبولها عليهم -حكم بانتقال ملكية عقار -التثبت يف حقوق القصر -تعديل الشهود -إقرار الورثة بالصورية -قضاء بانتقال امللكية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34262424:‬تاريخه ‪1434/07/09:‬هـ‬\n                         ‫رقم الدعوى ‪34259555:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34385604:‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n       ‫إثبــات ملكيــة عقــار ‪ -‬رهــن ‪ -‬إفــراغ صــوري ‪ -‬عــدم قبــول شــهادة عمــودي‬\n       ‫النســب لبعضهــم البعــض وقبولهــا عليهــم ‪ -‬حكــم بانتقــال ملكيــة‬\n       ‫عقــار‪ -‬التثبــت يف حقــوق القصــر‪ -‬تعديــل الشــهود‪ -‬إقــرار الورثــة‬\n                                         ‫بالصوريــة ‪ -‬قضــاء بانتقــال امللكيــة‪.‬‬\n\n\n\n\n       ‫‪ .1‬قــال ابــن قدامــه رحمــه اهلل يف املغنــى ( وإن كان اإلقــرار مــن اثنــن‬\n       ‫مــن الورثــة عدلــن مثــل أن يخلــف ثالثــة بنــن فيقــر اثنــان منهــم‬\n       ‫بالديــن ويشــهدا بــه فــان شــهادتهم تقبــل ويثبــت باقــي الديــن يف حــق‬\n          ‫املنكــر وبهــذا كلــه قــال احلســن والشــعبي والشــافعي وابــن املنــذر)‬\n       ‫‪ .2‬قــال صاحــب زاد املســتقنع ( ال تقبــل شــهادة عمــودي النســب وال‬\n                              ‫شــهادة احــد الزوجــن لصاحبــه وتقبــل عليهــم )‬\n\n\n\n\n       ‫دعــوى املدعــي ضــد ورثــة أخيــه ومــن ضمنهــم زوجــة أخيــه ووالــده‬\n       ‫والزوجــة أصالــة عــن نفســها ووكيلــة ووليــه علــى أوالدهــا ومضمــون‬\n       ‫الدعــوى انــه طلــب منــه مــورث املدعــى عليهــم أخــوه يف حياتــه أن يشــتري‬\n       ‫لــه ارض ـ ًا يف املدينــة املنــورة وســلم لــه مبلــغ مليــون ريــال وطلــب مــورث‬\n       ‫املدعــى عليهــم أن يفــرغ املدعــي ملــورث املدعــى عليهــم صــك عقــار ثــم‬\n\n‫‪481‬‬\n\f‫ذكــر موقعــه وأوصافــه يف نــص الضبــط وذلــك حتــى يتم إنهــاء إجراءات‬\n‫شــراء عقــاره يف املدينــة وقــد مت شــراء األرض ملــورث املدعــى عليهــم‬\n‫إال انــه تــويف قبــل إعــادة األرض للمدعــي ونقلهــا باســمه وطلــب املدعــي‬\n‫احلكــم بإعــادة األرض لــه ونقلهــا باســمه ‪ -‬أجــاب املدعــى عليهمــا‬\n‫ا ‪ -‬مت االستفســار عــن ســريان‬     ‫باملصادقــة علــى الدعــوى جملــة وتفصيـ ً‬\n‫مفعــول الصــك و مصــدره فتمــت اإلجابــة انــه ســاري املفعــول ‪ -‬صــدر‬\n‫احلكــم بانتقــال ملكيــة العقــار للمدعــي ‪ -‬مت رفــع احلكــم حملكمــة‬\n‫االســتئناف لتدقيقــه لوجــود قصــار يف القضيــة ‪ -‬وردت املعاملــة مــن‬\n‫محكمــة االســتئناف باملالحظــة بــان إقــرار املدعــى عليهمــا ال يكفــي‬\n‫بــل البــد مــن إثبــات دعــواه واإلقــرار يلــزم البالغــن فقــط ‪ -‬أجــاب ناظــر‬\n‫القضيــة بــان اإلقــرار يف حــق البالغــن يعتبــر إقــرار ًا يف حقهــم وشــهادة يف‬\n‫حــق غيرهــم كمــا نــص عليــه ابــن قدامــه يف املغنــى وغيــره ‪ -‬صــدر قــرار‬\n‫محكمــة االســتئناف باملالحظــة بأنــه البــد مــن لفــظ الشــهادة وشــهادة‬\n‫األب ال تقبــل البنــه وشــهادة الزوجــة غيــر كافيــة ‪ -‬احضــر املدعــي‬\n‫شــاهدين مت تعديلهمــا شــرع ًا ولــم يظهــر لناظــر القضيــة خــاف مــا‬\n‫حكــم بــه ‪ -‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة القائــم بعمــل رئيــس‬\n‫احملكمــة العامــة بينبــع برقــم ‪ 34259555‬وتاريــخ ‪ 1434/06/06‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341366056‬وتاريــخ ‪ 1434/06/06‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1434/06/11‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n\n                                                                                      ‫‪482‬‬\n\f      ‫وفيهــا حضــر‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم حلضــوره‬\n      ‫املدعــى عليهــا ‪ /‬ســعودية اجلنســية مبوجب الســجل املدنــي رقم واملعروف‬\n      ‫بهــا مــن قبــل ابنهــا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم أصالــة‬\n      ‫عــن نفســها وبالوكالــة عــن أوالدهــا وهــم‪ /‬و‪ /‬و‪ /‬أوالد مبوجــب‬\n      ‫الوكالــة رقــم ‪........‬وتاريخ‪1434/4/27‬ه ـ الصــادرة مــن كتابــة عــدل‬\n      ‫ينبــع واملخــول لهــا فيهــا حــق املرافعــة واملدافعــة وســماع الدعــاوى والــرد‬\n      ‫عليهــا واإلقــرار واإلنــكار وطلــب اليمــن وردهــا واالمتنــاع عنــه وإحضار‬\n      ‫البينــات والشــهود والطعــن فيهــا واإلجابــة واجلــرح والتعديــل وبالواليــة‬\n      ‫علــى ابنتهــا ‪........‬مبوجــب صــك الواليــة الصــادر مــن هــذه احملكمــة‬\n      ‫برقم‪........‬وتاريخ ‪1434/4/9‬هـ واملدعى عليه ‪ .......‬باكستاني اجلنسية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم واملدعــى عليهــم هــم ورثــة املتوفــى مبوجــب‬\n      ‫صــك حصــر الورثــة رقم‪34183141‬وتاريخ‪1434/4/9‬ه ـ الصــادر مــن‬\n      ‫هــذه احملكمــة وقــرر املدعــي قائــا إن مــورث املدعــى عليهــم أخــي قــد‬\n      ‫أعطانــي مبلــغ مليــون ريــال ألجــل أن أشــتري لــه أرض يف املدينــة املنــورة‬\n      ‫وطلــب منــي أن أرهنــه الصــك اململــوك لــي والصــادر مــن كتابــة عــدل‬\n      ‫املدينــة املنــورة برقــم ‪156‬وتاريخ‪1371/3/26‬ه ـ وقــد اشــتريت لــه أرض‬\n      ‫مبخطــط ‪........‬قبــل وفاتــه وســلمته صــك األرض ولــم يقــم بإعــادة الصــك‬\n      ‫لــي ونقلــه إلــى ملكــي أطلــب نقــل الصــك باســمي هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليهــم عمــا ذكــره املدعــي أجابــت بــأن مــا ذكــره املدعــي‬\n      ‫صحيــح جملــة وتفصيــا وقــد اســتلمنا صــك األرض التــي باســم مورثنــا‬\n      ‫وال مانــع لدينــا مــن نقــل الصــك رقــم ‪........‬وتاريخ‪1371/3/26‬ه ـ باســم‬\n      ‫املدعــي‪ ،‬كمــا أجــاب والــد املتــويف بواســطة مترجــم احملكمــة ‪........‬‬\n      ‫قائــا بــأن مــا ذكــره املدعــي صحيــح جملــة وتفصيــا وال مانــع لدينــا‬\n\n\n‫‪483‬‬\n\f‫مــن نقــل العقــار باســم املدعــي هكــذا أجــاب ولالستفســار عــن ســريان‬\n‫الصــك املذكــور بعاليــه رفعــت اجللســة وحــدد لهــم موعــد يف يــوم الســبت‬\n‫املوافق‪1434/7/15‬ه ـ الســاعة العاشــرة‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/11‬‬\n                                                                           ‫هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة القائــم بعمــل رئيــس‬\n‫احملكمــة العامــة بينبــع برقــم ‪ 34259555‬وتاريــخ ‪ 1434/06/06‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341366056‬وتاريــخ ‪ 1434/06/06‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1434/06/11‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر ‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر‬\n‫حلضــوره املدعــى عليهــا ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫واملعــرف بهــا مــن قبــل ابنهــا ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم أصالــة عــن نفســها وبالوكالــة عــن أوالدهــا وهــم مبوجــب الوكالــة‬\n‫رقــم ‪ 34519606‬وتاريــخ ‪1434/4/27‬ه ـ الصــادرة مــن كتابــة عــدل‬\n‫ينبــع واملخــول لهــا فيهــا حــق املرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار وطلــب اليمــن وردهــا واالمتنــاع عنــه‬\n‫وإحضــار البينــات والشــهود والطعــن فيهــا واإلجابــة واجلــرح والتعديــل‬\n‫وبالواليــة علــى ابنتهــا ‪ ........‬مبوجــب صــك الواليــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم‪ 34183382‬وتاريــخ ‪1434/4/9‬ه ـ واملدعــى عليــه‬\n‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم واملدعــى عليهــم‬\n‫هــم ورثــة املتوفــى مبوجــب صــك حصــر الورثــة رقــم‪ 34183141‬وتاريــخ‬\n‫‪1434/4/9‬ه ـ الصــادر مــن هــذه احملكمــة وقــرر املدعــي قائــا إن‬\n\n\n                                                                                  ‫‪484‬‬\n\f      ‫مــورث املدعــى عليهــم أخــي ‪ ........‬وقــد أعطانــي مبلــغ مليــون ريــال ألجــل‬\n      ‫أن أشــتري لــه أرض يف املدينــة املنــورة وطلــب منــي أن أرهنــه الصــك‬\n      ‫اململــوك لــي والصــادر مــن كتابــة عــدل املدينــة املنــورة برقــم ‪........‬‬\n      ‫وتاريخ‪1371/3/26‬ه ـ وقــد اشــتريت لــه أرض مبخطــط ‪........‬قبــل وفاته‬\n      ‫وســلمته صــك األرض ولــم يقــم بإعــادة الصــك لــي ونقلــه إلــى ملكــي‬\n      ‫أطلــب نقــل الصــك باســمي هــذه دعــواي وبســؤال املدعــى عليهــم عمــا‬\n      ‫ذكــره املدعــي أجابــت بــأن مــا ذكــره املدعــي صحيــح جملــة وتفصيــا‬\n      ‫وقــد اســتلمنا صــك األرض التــي باســم مورثنــا وال مانــع لدينــا مــن نقــل‬\n      ‫الصــك رقــم ‪........‬وتاريخ‪1371/3/26‬ه ـ باســم املدعــي‪ ،‬كمــا أجــاب‬\n      ‫والــد املتــويف بواســطة مترجــم احملكمــة قائــا بــأن مــا ذكــره املدعــي‬\n      ‫صحيــح جملــة وتفصيــا وال مانــع لدينــا مــن نقــل العقــار باســم املدعــي‬\n      ‫هكــذا أجــاب ولالستفســار عــن ســريان الصــك املذكــور بعاليــه رفعــت‬\n      ‫اجللســة‪ ،‬ويف يــوم الســبت املوافــق‪ 1434/07/08‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي واملدعــى عليهــم وقــد‬\n      ‫ســبق لــي مخاطبــة كتابــة عــدل املدينــة املنــورة لالستفســار عــن ســريان‬\n      ‫الصــك بكتابــي رقم‪341427599‬يف‪1434/6/13‬ه ـ فوردنــي جوابهــم‬\n      ‫برقم‪341427599‬يف‪1434/6/25‬ه ـ واملتضمــن أن الصــك مطابــق‬\n      ‫لســجله وســاري املفعــول وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n      ‫وإقــرار املدعــى عليهــم بصحــة مــا ذكــره املدعــي وعــدم ممانعتهــم مــن‬\n      ‫نقــل الصــك إلــى اســم املدعــي لــذا فقد حكمــت بانتقــال ملكية الصك‬\n      ‫رقــم (‪ )156‬وتاريــخ ‪1371/3/26‬ه ـ مــن ملــك مــورث املدعــى عليهــم إلــى‬\n      ‫ملــك املدعــي هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى‬\n      ‫املدعــى عليهــم قــرروا عــدم اعتراضهــم وقــررت رفــع املعاملــة حملكمــة‬\n\n\n‫‪485‬‬\n\f‫االســتئناف‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/08‬ه ـ ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق‪ 1434/10/07‬ه ـ فتحــت اجللســة الســاعة‬\n‫احلاديــة عشــر والنصــف وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مالحظــا عليهــا بالقــرار رقــم ‪ 34295407‬وتاريــخ ‪1434/8/13‬ه ـ وهــذا‬\n‫نص احلاجة منه ( وبدراسة الصك وصورة ضبطه تقرر إعادتها لفضيلة‬\n‫حاكمهــا ملالحظــة أنــه ال يكفــي إقــرار املدعــى عليهــم يف حــق القاصــر‬\n‫بــل البــد مــن مطالبــة املدعــي بإثبــات دعــواه واإلقــرار يلــزم البالغــن فقــط‬\n‫فعلــى فضيلتــه إجــراء الــازم نحــو مــا ذكــر واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ) أ‪.‬ه ـ قاضــي اســتئناف‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف د‪ .‬موافــق علــى مــا ذكــر أعــاه ولــه‬\n‫إضافــة ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه‪ ،‬وجوابــا علــى مــا‬\n‫ذكــره أصحــاب الفضيلــة حفظهــم اهلل فــإن إقــرار املدعــى عليهــم يعتبــر‬\n‫إقــرارا يف حقهــم وشــهادة يف حــق غيرهــم قــال ابــن قدامــة رحمــه اهلل يف‬\n‫املغنــي ( وإن كان اإلقــرار مــن اثنــن مــن الورثــة عدلــن مثــل أن يخلــف‬\n‫ثالثــة بنــن فيقــر اثنــان منهــم بالديــن ويشــهدا بــه فــإن شــهادتهم تقبــل‬\n‫ويثبــت باقــي الديــن يف حــق املنكــر وبهــذا كلــه قــال احلســن والشــعبي‬\n‫والشــافعي وابــن املنــذر ) وقــال صاحــب زاد املســتقنع ( ال تقبــل شــهادة‬\n‫عمــودي النســب وال شــهادة أحــد الزوجــن لصاحبــه وتقبــل عليهــم)‪،‬‬\n‫هــذا مــا لــزم اجلــواب عنــه‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/07‬ه ـ ‪.‬‬\n‫ويف يــوم اإلثنــن املوافــق‪ 1434/12/02‬ه ـ افتتحــت اجللســة الســاعة‬\n‫احلاديــة عشــر وفيهــا حضــر املدعــي وقــد عــادت املعاملــة مــن محكمــة‬\n\n\n                                                                                        ‫‪486‬‬\n\f      ‫االستئناف مالحظا عليه بالقرار رقم ‪ 34344453‬يف ‪1434/10/29‬هـ‬\n      ‫وهــذا نــص احلاجــة منــه ( وبدراســة الصــك وصــورة ضبطــه تقــرر إعادتهــا‬\n      ‫لفضيلتــه حاكمهــا ملالحظــة مــا يلــي مــا أجــاب بــه فضيلتــه غيــر مقنــع‬\n      ‫فإقــرار باقــي الورثــة لــم يقــع بلفــظ الشــهادة وأن مــن أقــر لــدى فضيلتــه‬\n      ‫مــن الورثــة هــم والــد املدعــي وزوجــة املتوفــى فلــو شــهدا للمدعــي بلفــظ‬\n      ‫الشــهادة ملــا قبلــت شــهادة والــده ألن شــهادة عمــودي النســب ال تقبــل يف‬\n      ‫حــق املشــهود لــه وتقبــل عليــه كمــا هــو يف نــص ابــن قدامــه الــذي ذكــره‬\n      ‫فضيلتــه وأمــا شــهادة زوجــة املتوفــى فلــم تكــن بينــة كاملــة وال بــد مــن‬\n      ‫اكتمــال نصــاب البينــة وتثبــت عدالتهــا والقصــار يجــب االحتيــاط يف‬\n      ‫حقهــم فعلــى فضيلتــه مالحظــة ذلــك واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم) قاضــي اســتئناف ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه د‪ .‬أ‪.‬ه ـ‬\n      ‫‪ ،‬فســألت املدعــي هــل لديــك زيــادة بينــة علــى مــا ذكــر ســابقا فقــال‬\n      ‫نعــم إننــي أحضــرت كال مــن الشــاهد ‪ /‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم املولــود يف ‪1386/2/10‬ه ـ والــذي يعمــل موظــف يف‬\n      ‫وزارة الصحــة ولــدى ســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل أننــي‬\n      ‫ســمعت ‪........‬رحمــه اهلل قبــل وفاتــه يقــول إن بيــع العمــارة الواقعــة يف‬\n      ‫‪........‬الــذي حصــل بينــي وبــن أخــي صــوري وال حقيقــة لــه هكــذا شــهد‬\n      ‫كمــا حضــر الشــاهد ‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫واملولــود يف ‪1383/2/10‬ه ـ والــذي يعمــل يف شــركة ‪........‬ولــدى ســؤاله‬\n      ‫عمــا لديــه مــن شــهادة قــال أشــهد هلل إننــي ســمعت قبــل وفاتــه يقــول إن‬\n      ‫البيــت الواقــع يف ‪........‬والــذي مــدون بإســمي ملــك ألخــي وليــس ملــك لــي‬\n      ‫هكــذا شــهد فطلبــت مــن املدعــي إحضــار معدلــن فأحضــر كال مــن‬\n\n\n‫‪487‬‬\n\f‫‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم و ‪ /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ولــدى ســؤالهما عمــا لديهمــا قــاال نشــهد‬\n‫هلل بــأن الشــاهدين ثقتــان عــدالن مقبــوال الشــهادة هكــذا شــهدا وبنــاء‬\n‫علــى مــا ســبق لــم يظهــر لــي ســوى مــا حكمــت بــه وقــررت بعــث املعاملــة‬\n‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/12/02‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ -‬وبعــد فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة الثانية لألحوال الشــخصية واألوقاف والوصايا‬\n‫والقصار وبيوت املال مبحكمة االســتئناف يف منطقة مكة املكرمة‬\n‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة‬\n‫العامــة بينبــع برقــم ‪ 34262424‬وتاريــخ ‪1434/7/9‬ه ـ املتضمــن دعوى‪/‬‬\n‫ضــد‪ /‬ورثــة يف ملكيــة عقــار وبدراســة الصــك وصــورة ضبطــه تقــررت‬\n‫املوافقــة علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى‬\n                          ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪،،،،،،،‬‬\n\n\n\n\n                                                                                     ‫‪488‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":481,"source_page_end":488,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7e1fbe4bc7a3ef25cf0d6ad6d44791ac731f01cb02ab0042cea3cc801e2e683","normalized_text_hash":"2133e64624777f5e53717475e9e2e92b5e6fbdf68dd9611d861510ae328a8d20","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p481-34262424"},{"id":"22e2da0d-2f45-5cce-9847-bb73f9d5e3ed","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أرض بدون صك -تخلف املدعى عليه عن احلضور رغم تبليغه -اإلتفاق على تطبيق منحة سامية بنسب -مطالبة املدعى بإفراغ نصيبه من األرض بصك -عدم معرفة املدعى لرقم","document_number":"34269799","case_number":"347574","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/16","year":"1434","subject":"عقار -شراء أرض بدون صك -تخلف املدعى عليه عن احلضور رغم تبليغه -اإلتفاق على تطبيق منحة سامية بنسب -مطالبة املدعى بإفراغ نصيبه من األرض بصك -عدم معرفة املدعى لرقم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34269799 :‬تاريخه ‪1434/7/16:‬هـ‬\n                           ‫رقم الدعوى ‪347574 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34314737:‬تاريخه‪1434/09/08:‬هـ‬\n\n\n      ‫عقــار‪ -‬شــراء أرض بــدون صــك‪ -‬تخلــف املدعــى عليــه عــن احلضــور‬\n      ‫رغــم تبليغــه‪ -‬اإلتفــاق علــى تطبيــق منحــة ســامية بنســب‪ -‬مطالبــة‬\n      ‫املدعــى بإفــراغ نصيبــه مــن األرض بصــك‪ -‬عــدم معرفــة املدعــى لرقــم‬\n      ‫أو تاريــخ الصــك‪ -‬اخلصــم يف دعــوى العــن هــو مــن كانــت العــن حتت‬\n        ‫يــده‪ -‬صــرف النظــر عــن دعــوى املدعــى وإخــاء ســبيل املدعــى عليــه‪.‬‬\n\n\n\n      ‫اخلصــم يف الدعــوى هــو ذو اليــد كمــا جــاء يف املوســوعة الفقهيــة‬\n      ‫والقاعــدة يف ذلــك أن مــن ادعــى علــى انســان شــيئ ًا فــإن كان املدعــى‬\n      ‫عليــه لــو أقــر يصــح إقــراره ويترتــب عليــه حكــم فإنــه يكــون بإنــكاره‬\n      ‫خصمـ ًا يف الدعــوى ويصــح توجيههــا إليــه أمــا اذا كان ال يترتــب علــى‬\n      ‫إقــراره حكــم لــم يكــن خصمـ ًا بإنــكاره وبنــاء عليــه حدد الفقهــاء اخلصم‬\n                            ‫يف دعــاوى العــن بأنــه مــن كانــت العــن حتــت يــده‬\n\n\n\n\n      ‫حضــر املدعــى ولــم يحظــر املدعــى عليــه مــع تبلغــه‪ -‬أذنــت احملكمــة‬\n      ‫بســماع الدعــوى فادعــى املدعــى بأنــه اشــترى أرضـ ًا من أحد األشــخاص‬\n      ‫وذكــر موقعهــا وحدودهــا وأطوالهــا ومســاحتها وأن هــذا الشــراء بــدون‬\n      ‫صــك‪ -‬قــرر املدعــى بأنــه اتفــق مــع املدعــى عليــه علــى أن يقــوم املدعــى‬\n\n‫‪489‬‬\n\f‫عليــه بتطبيــق منحــه ســامية علــى هــذه األرض ويكــون لــه ولصاحــب‬\n‫املنحــة ‪ % 40‬مــن األرض و ‪ % 20‬للوســطاء والنســبة الباقيــة ‪% 40‬‬\n‫للمدعــى قــام املدعــى عليــه بتطبيــق املنحــة ألحــد األشــخاص‪ -‬طلــب‬\n‫املدعــى إلــزام املدعــى عليــه بــأن يفــرغ لــه نصيبــه مــن األرض ‪-% 40‬‬\n‫جــرى ســؤال املدعــى عــن الصــك الــذي يريــد احلكــم لــه فذكــر أنــه‬\n‫ال يعلــم رقمــه وال تاريخــه وأنــه باســم شــخص غيــر املدعــى عليــه‪ -‬ملــا‬\n‫تقــرر مــن أن اخلصــم يف الدعــوى هــو ذو اليــد وهــو مــن يصــح إقــراره والن‬\n‫العــن موضــع الدعــوى ليســت حتــت يــد املدعــى عليــه لــذا صــدر احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــى وإفهــام املدعــى بأنــه لــه إقامــة دعــواه‬\n‫علــى مــن بيــده العــن‪ -‬اعتــرض املدعــى علــى احلكــم‪ -‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم‬\n‫‪ 347574‬وتاريــخ ‪1434/01/05‬ه ـ املقيــدة باحملكمــة برقــم ‪3434186‬‬\n‫وتاريــخ ‪1434/01/05‬ه ـ حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقم‪...‬ولــم يحضــر املدعــى عليــه ‪ ...‬وال مــن ينــوب عنــه وقــد تبلــغ‬\n‫باملوعــد فادعــى ‪ ...‬قائــا أن مــن اجلــاري يف ملكــي األرض الواقعــة‬\n‫خلــف ‪ ......‬بحــي ‪ .....‬مبحافظــة جــدة ويحدهــا مــن الشــرق شــارع عرضــه‬\n‫ثالثــون متــرا بطــول مائتــن وخمســة وثالثــن متــرا وأربعــن ســنتمترا‬\n‫ومــن الشــمال شــارع عرضــه خمســة وثالثــون متــرا بطــول مائتــن وثالثني‬\n\n                                                                                     ‫‪490‬‬\n\f      ‫متــرا وســبعني ســنتمترا ومــن اجلنــوب شــارع عرضــه ثالثــون متــرا ثــم‬\n      ‫مخطــط العيســائي بطــول مائتــن وخمســة وثالثــن متــرا وأربعــن‬\n      ‫ســنتمترا ومــن الغــرب شــارع عرضــه خمســة عشــر متــرا ثــم مخطــط‬\n      ‫زهــرة الوزيريــة بطــول مائتــن وعشــرة أمتــار وخمســة وســبعني ســنتمترا‬\n      ‫ومســاحتها العامــة تســعة وأربعــون ألفــا ومائتــان وواحــد وثمانــون متــرا‬\n      ‫مربعــا وثالثمائــة وثمانــون ســنتمترا مربعــا وقــد اشــتريتها مــن ‪ ...‬وليــس‬\n      ‫لهــا صــك مببلــغ وقــدره خمســة ماليــن ريــال ثــم اتفقــت مــع املدعــى عليــه‬\n      ‫علــى ان يقــوم بتطبيــق منحــة ســامية علــى األرض ويكــون لــه ولصاحــب‬\n      ‫املنحــة نســبة مــن األرض وقدرهــا ‪ %40‬ويكــون للوســطاء بينــي وبينــه‬\n      ‫نســبة وقدرهــا ‪ %20‬ويكــون لــي النســبة الباقيــة مــن األرض وقدرهــا‬\n      ‫‪ % 40‬وقــد قــام املدعــى عليــه بتطبيــق منحــة ســامية تعــود ‪...‬علــى كامــل‬\n      ‫األرض ومت اســتخراج صــك باســم ‪ ...‬وعندمــا طالبــت املدعــى عليــه‬\n      ‫بإفــراغ األرض لــي ماطلنــي لــذا أطلــب احلكــم علــى املدعــى عليــه بإفراغ‬\n      ‫نصيبــي مــن األرض وقــدره ‪ % 40‬هــذه دعــواي فجــرى ســؤال املدعــي عــن‬\n      ‫الصــك الــذي يريــد اإلفــراغ لــه منــه فقال إنني ال أعــرف رقمه وال تاريخه‬\n      ‫ولكنــه باســم ‪...‬هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى ومــا‬\n      ‫قــرره املدعــي مــن أن الصــك الــذي يريــد احلكــم لــه علــى املدعــى عليــه‬\n      ‫باالفــراغ منــه مســجل باســم ‪...‬وملــا تقــرر مــن أن اخلصــم يف الدعوى هو ذو‬\n      ‫اليــد جــاء يف املوســوعة الفقهيــة ( والقاعــدة يف ذلــك ‪ :‬أن مــن ادعــى علــى‬\n      ‫إنســان شــيئًا ‪ ،‬فــإن كان املدعــى عليــه لــو أقــر يصــح إقــراره ‪ ،‬ويترتــب‬\n      ‫خصمــا يف الدعــوى ‪ ،‬وتصــح‬   ‫ً‬        ‫عليــه حكــم ‪ ،‬فإنــه يكــون بإنــكاره‬\n      ‫بتوجيههــا إليــه ‪ .‬أمــا إذا كان ال يترتــب علــى إقــراره حكــم لــم يكــن‬\n      ‫ـاء علــى هــذه القاعــدة حــدد الفقهــاء اخلصــم يف‬  ‫خصمــا بإنــكاره ‪ ،‬وبنـ ً‬\n                                                                                  ‫ً‬\n\n‫‪491‬‬\n\f‫مختلــف أنــواع الدعــاوى ‪ :‬أ ‪ -‬ففــي دعــاوى العــن يكــون اخلصــم مــن‬\n‫كانــت هــذه العــن يف يــده ‪ .‬وذلــك ألن أي شــخص ليســت العــن املدعــاة‬\n‫يف يــده ليــس لــه أن يقربهــا ‪ ،‬واحلائــز لهــا هــو الــذي ميلــك أن يقربهــا‬\n‫‪ ،‬فهــو إذن اخلصــم يف دعواهــا ) لــذا كلــه فقــد صرفــت النظــر عــن‬\n‫دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه منــه وبــه حكمــت وأفهمــت‬\n‫املدعــي بــأن لــه إقامــة الدعــوى علــى مــن بيــده العــن إن أراد وبعــرض‬\n‫احلكــم علــى املدعــي قــرر عــدم القناعــة وطلــب التمييــز فأجيــب لطلبــه‬\n‫وجــرى إفهامــه بتعليمــات اإلعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/15‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n‫يــوم األحــد املوافــق ‪ 1434/10/25‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34314737‬يف‬\n‫‪1434/09/08‬ه ـ ونــص احلاجــة منــه ‪( :‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ) قاضــي‬\n‫اســتئناف ‪ ...‬ختــم وتوقيــع قاضــي اســتئناف ‪ -...‬لــي وجهــة نظــر ‪ -‬ختــم‬\n‫وتوقيــع رئيــس الدائــرة ‪...‬ختــم وتوقيــع ‪ ،‬وأمــرت بإثبــات ذلــك علــى‬\n‫ضبطــه وســجله حتــى ال يخفــى ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/25‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جــده برقــم ‪ 34/34186‬وتاريــخ‬\n‫‪1434/8/17‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬‬\n\n\n                                                                                   ‫‪492‬‬\n\f      ‫القاضــي باحملكمــة العامــة مبحافظــة جــده برقــم ‪ 34269799‬وتاريــخ‬\n      ‫‪1434/7/16‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ...‬ضــد ‪ ، ...‬وبدراســة الصك وصورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم‪.‬‬\n\n\n\n\n‫‪493‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":489,"source_page_end":493,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4ad356eee9d50892d9a2980b45185b612e4d57a066b08e350e90df60da5a6a8e","normalized_text_hash":"75e126569d73328121dd2daae15dbc17f37bae689aa8422c4bf375e72320d9b9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p489-34269799"},{"id":"e2824ed6-db70-5096-8ec2-a1d17c4d705e","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -هبه -إفراغ العقار للشريك من أجل االستفادة من قرض صندوق التنمية العقاري -الهبة املشروطة -املطالبة بإعادة األرض بينة موصلة للمدعي على دعواه -احلكم املتنازل عنها -عدم وجود برد دعوى املدعي وإخاء سبيل املدعى عليه منها وإفهام املدعي بأن له مين املدعى عليه متى طلبها.","document_number":"34291856","case_number":"3450976","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف من قبله بنظر القضية","circuit":"الدائرة احلقوقية الثانية برقم 34328035يف 1434/10/12ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"عقار -هبه -إفراغ العقار للشريك من أجل االستفادة من قرض صندوق التنمية العقاري -الهبة املشروطة -املطالبة بإعادة األرض بينة موصلة للمدعي على دعواه -احلكم املتنازل عنها -عدم وجود برد دعوى املدعي وإخاء سبيل املدعى عليه منها وإفهام املدعي بأن له مين املدعى عليه متى طلبها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34291856:‬تاريخه ‪1434/8/8:‬هـ رقم‬\n                          ‫الدعوى ‪3450976:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 34328035:‬تاريخه‪1434/10/12:‬هـ‬\n\n\n ‫عقــار‪ -‬هبــه‪ -‬إفــراغ العقــار للشــريك مــن أجــل االســتفادة مــن قــرض‬\n ‫صنــدوق التنميــة العقــاري‪ -‬الهبــة املشــروطة‪ -‬املطالبــة بإعــادة األرض‬\n ‫بينــة موصلــة للمدعــي علــى دعــواه‪ -‬احلكــم‬ ‫املتنــازل عنهــا‪ -‬عــدم وجــود ّ‬\n ‫بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه منهــا وإفهــام املدعــي‬\n                                  ‫بــأن لــه ميــن املدعــى عليــه متــى طلبهــا‪.‬‬\n\n\n\n ‫قولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــى واليمــن علــى مــن‬\n                                                                       ‫أنكــر )‬\n\n\n\n ‫ادعــى املدعــى بــأن املدعــى عليــه أخــوه كان شــريكا لــه يف قطعه أرض‬\n ‫مبوجــب صــك وذكــر حدودهــا وأطوالهــا ومســاحتها‪ -‬طلــب املدعــى‬\n ‫مــن أخيــه املدعــى عليــه أن يتنــازل لــه عــن نصيبــه وأثبــت أن التنــازل‬\n ‫هبــه حتــي يتمكــن مــن احلصــول علــى قــرض الصنــدوق العقــاري ثــم‬\n ‫يقومــا ببنــاء العمــارة‪ -‬قــام املدعــى بالتنــازل ألخيــه املدعــى عليــه وأفــرغ‬\n ‫نصيبــه وهمــش بذلــك علــى صــورة امللــك بأنــه انتقــل نصيــب املدعــى‬\n ‫بالهبــة لشــريكه ( املدعــى عليــه ) وذلــك هبــه بــدون مقابــل‪ -‬وافــق‬\n ‫صنــدوق التنميــة العقــاري علــى القــرض‪ -‬طلــب املدعــى مــن املدعــى‬\n\n\n                                                                                        ‫‪494‬‬\n\f      ‫عليــه البــدء يف البنــاء ورفــض ذلــك املدعــى عليــه وقــام باالســتيالء علــى‬\n      ‫األرض والقــرض‪ -‬طلــب املدعــى احلكــم لــه بإعــادة نصــف األرض‬\n      ‫موضــع الدعــوى‪ -‬أقــر املدعــى عليــه بالشــراكة كمــا أقــر بالهبــة وأنهــا‬\n      ‫غيــر مشــروطة وأنكــر االتفــاق املذكــور فيمــا يخــص صنــدوق التنميــة‬\n      ‫العقــاري‪ -‬بســؤال املدعــى عــن بينتــه قــرر أنــه ال بينــه لديــه وأن االتفــاق‬\n      ‫بنــاء علــى اإلخــوة‪ -‬يف جلســة أخــرى أحضــر املدعــي شــاهد ًا ويعمــل يف‬\n      ‫مكتب عقار وشــهد بأن األرض موضع الدعوى اشــتراها املدعى وقال‬\n      ‫ســوف أشــرك أخــي ( املدعــى عليــه ) يف العقــار‪ -‬قــرر املدعــى عليــه بــأن‬\n      ‫الشــهادة غيــر صحيحــة وأن الــذي اشــترى األرض هــو والدهمــا‪ -‬جــرى‬\n      ‫الرجــوع الــى صــك األرض وهــو مطابــق ملــا ذكــر والهبــة بــدون مقابــل‪-‬‬\n      ‫جــرى إفهــام املدعــى بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه ألن‬\n      ‫الشــاهد الــذي أحضــره شــهادته غيــر موصلــه‪ -‬قــرر املدعــى أنــه اليطلــب‬\n      ‫ميــن املدعــى عليــه‪ -‬صــدر احلكــم بــرد دعــوى املدعــى جتــاه املدعــى عليه‬\n      ‫واخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى وجــرى افهــام املدعــى‬\n      ‫بــأن لــه ميــن املدعــى عليــه متــي طلبهــا‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                             ‫االســتئناف‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي املتــدرب لــدى فضيلة الشــيخ‬\n      ‫‪...‬القاضــي يف احملكمــة العامــة بالريــاض واملكلــف مــن قبلــه بنظــر‬\n      ‫القضيــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3450976‬وتاريــخ ‪ 1434/01/28‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34252702‬وتاريــخ ‪ 1434/01/28‬ه ـ ففــي‬\n\n‫‪495‬‬\n\f‫يــوم الثالثــاء املوافــق‪ 1434/06/06‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي ‪...‬ويحمــل الســجل املدنــي رقــم ‪...‬كمــا حضــر املدعــى عليــه‬\n‫‪...‬ويحمــل الســجل املدنــي رقــم ‪...‬وادعــى األول قائــا ‪ :‬إن املدعــى عليــه‬\n‫كان شــريكا لــي يف قطعــة أرض مملوكــة لنــا مشــاركة بالنصــف‬\n‫مبوجــب الصــك رقــم ‪ 1/566‬وتاريــخ ‪1400/04/02‬ه ـ والواقعــة يف‬\n‫شــرق حــي ‪...‬بطريــق خريــص بالريــاض مبوجــب املخطــط رقــم ‪1932‬‬\n‫لعــام ‪1397‬ه ـ وحــدوده وأطوالــه ‪ :‬شــماال قطعــة رقــم ‪ 1213‬بطــول ســتة‬\n‫وعشــرون متــرا ‪ ،‬وجنوبــا شــارع عــرض خمســة عشــر متــرا بطــول ســتة‬\n‫وعشــرون مترا ‪ ،‬وشــرقا القطعة رقم ‪ 1218‬بطول ثالثون مترا ‪ ،‬وغربا‬\n‫القطعــة رقــم ‪ 1220‬بطــول ثالثــون متــرا ‪ ،‬ومجمــوع مســاحتها ســبعمائة‬\n‫وثمانــون متــر مربــع ‪ ،‬مبوجــب الصــك الشــرعي الصــادر مــن كتابــة‬\n‫العــدل األولــى بالريــاض برقــم ‪ 7/267‬وتاريــخ ‪96/06/22‬ه ـ ورغبــة‬\n‫منــي يف التقــدمي علــى الصنــدوق العقــاري فقــط طلبت مــن أخي أن أتنازل‬\n‫لــه عــن نصيبــي وأثبــت أن التنــازل هبــة حتــى أمتكــن مــن احلصــول علــى‬\n‫القــرض مــن الدولــة ونقــوم ببنــاء العمــارة وفعــا قمــت بالتنــازل وأفــرغ‬\n‫ذلــك كمــا هــو مهمــش يف الصــك أعــاه وفيــه ‪ « :‬أنــه انتقــل نصيــب ‪......‬‬\n‫ممــا هــو مملــوك بهــذا الصــك بالهبــة لشــريكه ‪...‬يف ‪1409/02/07‬ه ـ‬\n‫وذلــك هبــة بــدون مقابــل « وبعــد أن وافــق الصنــدوق علــى القــرض طلبــت‬\n‫منــه البــدء يف البنــاء ورفــض ذلــك ويرغــب يف االســتيالء علــى األرض‬\n‫والقــرض بــدون وجــه حــق ‪ ،‬أطلــب احلكــم لــي بإعــادة نصــف األرض‬\n‫موضــوع الدعــوى هــذه دعــواي ‪ ،‬وبعــرض دعــوى املدعــي علــى املدعــى‬\n‫عليــه قــال ‪ :‬مــا ذكــره املدعــي مــن أنــه شــريك لــي يف قطعــة األرض‬\n‫املوصوفــة أعــاه فهــو صحيــح ‪ ،‬ولكنــه وهبهــا لــي هبــة ‪ ،‬وغيــر صحيــح‬\n\n\n                                                                                  ‫‪496‬‬\n\f      ‫مــا ذكــر أنــه مت االتفــاق فيمــا يخــص الصنــدوق العقــاري هكــذا أجــاب‬\n      ‫‪ ،‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬بــل الصحيــح مــا ذكرتــه ســابقا‬\n      ‫مــن االتفــاق ‪ ،‬وبســؤاله عــن بينتــه قــال‪ :‬ليــس لــدي أي بينــة ‪ ،‬إمنــا كان‬\n      ‫االتفــاق بنــاء علــى األخــوة هكــذا أجــاب ‪ ،‬ثــم جــرى منــا طلــب صــك‬\n      ‫ملكيــة األرض فأبــرز كل واحــد منهمــا صــكا لــأرض ‪ ،‬وقــال‬\n      ‫املدعــى عليــه بــأن الصــك الــذي معــه هــو بــدل مفقــود ‪ ،‬وســوف يجــري‬\n      ‫منــا بعثهمــا لكتابــة العــدل مــن أجــل االستفســار حيــال ســريان مفعولــه‬\n      ‫وكذلــك إجــراء الــازم حيــال الصــك األول ويف جلســة أخــرى بتاريــخ‬\n      ‫‪ 1434/08/08‬ه ـ حضــر املدعــي واملدعــى عليــه احلاضــران يف اجللســة‬\n      ‫الســابقة ‪ ،‬وقــد وردنــا كتــاب رئيــس كتابــة العــدل برقــم ‪341423668‬‬\n      ‫وتاريــخ ‪1434/06/28‬ه ـ واملتضمــن مــا نصــه ‪ « :‬بعــد الرجــوع إلــى‬\n      ‫ســجل الصــك رقــم ‪ 1/566‬تبــن أنــه محجــوز حســب النمــوذج اآللــي‬\n      ‫املرفــق وبنــاء علــى اخلطــاب الصــادر مــن قبلكــم برقــم ‪34/505367‬‬\n      ‫يف ‪1434/02/27‬ه ـ لوجــود دعــوى « أ‪.‬ه ـ ـ ‪ ،‬وقــد ســبق منــا اإلطــاع‬\n      ‫علــى صــك العقــار فوجــد مطابقــا ملــا وصــف يف الدعــوى ‪ ،‬وجــرى ســؤال‬\n      ‫املدعــي هــل لديــه زيــادة بينــة ؟ فقــال‪ :‬لــدي بينــة ‪ ،‬وأحضــر معــه للشــهادة‬\n      ‫‪...‬ويحمــل الســجل املدنــي رقــم ‪ ،...‬وقــال ‪ :‬أنــا مــن مواليــد عــام ‪1363‬ه ـ‬\n      ‫‪ ،‬وأســكن يف حــي اخلليــج يف الريــاض ‪ ،‬وأعمــل يف مكتــب عقــار ‪،‬‬\n      ‫وليــس لــي صلــة أو قرابــة باخلصمــن ‪ ،‬وبســؤاله عــن شــهادته ‪ ،‬قــال ‪:‬‬\n      ‫« أشــهد بــأن األرض املتنــازع عليهــا واملوصوفــة يف العقــد قــد اشــتراها‬\n      ‫منــي ‪...‬وقــال ســوف اشــرك أخــي ‪ ...‬يف العقــار « هكــذا شــهد ‪ ،‬وبســؤال‬\n      ‫املدعــي عليــه عــن الشــاهد ومــا جــاء يف شــهادته ‪ ،‬قــال ‪ :‬ال أطعــن يف‬\n      ‫الشــهاد بشــيء ولكــن مــا جــاء يف الشــهادة غيــر صحيــح ‪ ،‬بــل الــذي‬\n\n\n‫‪497‬‬\n\f‫اشــترى العقــار هــو الوالــد هكــذا أجــاب ‪ .‬كمــا جــرى ســؤال املدعــى‬\n‫عليــه مــا ســبب الهبــة ؟ فقــال ‪ :‬ال يوجــد ســبب ‪ ،‬بــل هــو مــن وهبهــا لــي‬\n‫بــدون مــا أطلــب منــه هكــذا أجــاب ‪ .‬فجــرى إفهــام املدعــي بــأن لــه‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواه بــأن العقــار املوصــوف يف الدعــوى‬\n‫واململــوك بالصــك رقــم ‪ 1/566‬وتاريــخ ‪1400/04/02‬ه ـ الصــادر مــن‬\n‫كتابــة العــدل األولــى بالريــاض هــو ملــك للمدعــى عليــه ولــم تكــن‬\n                   ‫الهبــة منــك مشــروطة بــأي شــرط فقــال‪ :‬ال أطلــب ميينــه‬\n‫هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وألن األصــل‬\n‫يف الصكــوك الصحــة والســامة علــى ظاهرهــا ‪ ،‬وألن املدعــي يدعــي‬\n‫بصوريــة هبتــه العقــار اململــوك بالصــك ذي الرقــم ‪ 1/566‬وتاريــخ‬\n‫‪1400/04/02‬ه ـ الصــادر مــن كتابــة العــدل األولــى بالرياض للمدعى‬\n‫عليــه وإنــكار املدعــى عليــه ذلــك ومبــا أن املدعــي قــرر بأنــه ال بينــة‬\n‫لديــه ســوى الشــاهد ‪ ،‬ولكــون بينتــه غيــر موصلــة ‪ ،‬ولرفــض املدعــي‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواه ولقولــه صلــى اهلل عليــه وآلــه وســلم‬\n‫‪« :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر» ‪،‬لذلــك كلــه فقــد‬\n‫رددت دعــوى املدعــي جتــاه املدعــى عليــه بشــأن هــذه الدعــوى وأخليــت‬\n‫ســبيله منهــا وبــه حكمــت ‪ ،‬وأفهمــت املدعــي بــأن لــه ميــن املدعــى‬\n‫عليــه متــى طلبهــا وبعــد إعالنــه قنــع بــه املدعــى عليــه ولــم يقنــع بــه‬\n‫املدعــي واســتعد بتقــدمي الئحــة اعتراضيــة فأفهمتــه بــأن عليــه مراجعــة‬\n‫احملكمــة يــوم االثنــن ‪1434/08/15‬هـ ـ الســتالم نســخة مــن احلكــم‬\n‫وأن لــه ثالثــن يومـ ُا تبــدأ مــن تاريــخ موعــد اســتالم نســخة احلكــم يقــدم‬\n‫الئحتــه االعتراضيــة خاللهــا وأنــه إذا مضــت املــدة ولــم يقــدم خاللهــا‬\n‫الالئحــة فيســقط حقــه يف االعتــراض ويكتســب احلكــم القطيعــة‪،‬‬\n\n\n                                                                                     ‫‪498‬‬\n\f      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                        ‫‪ .‬حــرر يف ‪ 1434/08/08‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪ 1434/10/25‬ه ـ‬\n      ‫لــدي أنــا ‪ .......‬القاضــي باحملكمــة العامــة بالريــاض ونظــرا النتهــاء‬\n      ‫فتــرة مالزمــة الشــيخ ‪ .........‬لدينــا فقــد افتتحــت اجللســة هــذا و قــد‬\n      ‫وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف بكتابــه ذي الرقــم‬\n      ‫‪ 342126177‬يف ‪ 1434/10/18‬ه ـ املرفــق بــه القــرار الصــادر مــن‬\n      ‫الدائــرة احلقوقيــة الثانيــة برقــم ‪ 34328035‬يف ‪ 1434/10/12‬ه ـ‬\n      ‫واملتضمــن أنــه لــم يظهــر لألكثريــة مــا يوجــب املالحظــة وجــرى قفــل‬\n      ‫اجللســة ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه أجمعــن حــرر يف ‪ 1434/10/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n                                       ‫مــن فضيلــة رئيــس احملكمــة العامــة بالرياض‬\n      ‫برقــم ‪ 342126177‬وتاريــخ ‪1434/09/5‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة القاضــي الشــيخ ‪.../‬املســجل برقــم ‪ 34291856‬وتاريــخ‬\n      ‫‪1434/08/8‬ه ـ اخلــاص بدعوى‪.../‬ضــد‪... /‬وبدارســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب‬\n      ‫املالحظــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                  ‫وســلم ‪.‬‬\n\n\n\n\n‫‪499‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":494,"source_page_end":499,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f3bd6e3fc0ba38966a1c0e8d25d985e2e03a14931f85afdcdc2c311a29bbfe8a","normalized_text_hash":"4361e8332ad4e7189cf597423d78121cb75fa599bf2279a725ac5bde17875d55","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p494-34291856"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

